/**
 * 创建攻击方块动画
 * @param startRowY 起始行位置
 * @param blockCount 创建的方块数量
 */
private createAttackBlocks(startRowY: number, blockCount: number = 5): void {
    if (!this.img_js) return;
    
    // 计算目标位置（img_js组件的全局位置）
    let targetPoint = new Laya.Point(this.img_js.width / 2, this.img_js.height / 2);
    let targetGlobalPos = this.img_js.localToGlobal(targetPoint);
    
    // 计算起始位置（消除行的中心位置）
    let startPoint = new Laya.Point(this.blockContainer.width / 2, this.offsetY + startRowY * (this.BLOCK_SIZE + this.BLOCK_GAP));
    let startGlobalPos = this.blockContainer.localToGlobal(startPoint);
    
    // 创建多个攻击方块
    for (let i = 0; i < blockCount; i++) {
        // 创建攻击方块
        let attackBlock = this.createAttackBlock();
        if (!attackBlock) continue;
        
        // 添加到场景根节点
        this.addChild(attackBlock);
        
        // 设置起始位置（添加随机偏移）
        let offsetX = (Math.random() - 0.5) * 100; // 随机水平偏移
        let offsetY = (Math.random() - 0.5) * 50;  // 随机垂直偏移
        attackBlock.x = startGlobalPos.x + offsetX;
        attackBlock.y = startGlobalPos.y + offsetY;
        
        // 创建抛物线动画，每个方块延迟不同时间
        this.createParabolaAnimation(attackBlock, targetGlobalPos, i * 0.1);
    }
}

/**
 * 创建单个攻击方块
 */
private createAttackBlock(): Laya.Sprite {
    // 使用方块池创建方块
    let block = this.getBlockFromPool() as Laya.Image;
    if (!block) return null;
    
    // 设置方块外观（使用随机颜色）
    const randomColorIndex = Math.floor(Math.random() * BLOCK_COLORS.length);
    const color = BLOCK_COLORS[randomColorIndex];
    block.skin = GameResourceManager.getSquareIcon(color);
    
    // 设置方块大小（比正常方块小一些）
    block.width = this.BLOCK_SIZE * 0.8;
    block.height = this.BLOCK_SIZE * 0.8;
    
    // 设置锚点为中心
    block.pivotX = block.width / 2;
    block.pivotY = block.height / 2;
    
    return block;
}

/**
 * 创建抛物线动画
 * @param block 要动画的方块
 * @param targetPos 目标位置
 * @param delay 延迟时间（秒）
 */
private createParabolaAnimation(block: Laya.Sprite, targetPos: Laya.Point, delay: number): void {
    if (!block) return;
    
    // 计算动画参数
    const startX = block.x;
    const startY = block.y;
    const endX = targetPos.x;
    const endY = targetPos.y;
    
    // 计算抛物线的控制点（中点上方）
    const midX = (startX + endX) / 2;
    const midY = Math.min(startY, endY) - 100; // 抛物线顶点
    
    const duration = 1000; // 动画持续时间（毫秒）
    
    // 延迟执行动画
    Laya.timer.once(delay * 1000, this, () => {
        // 添加旋转动画
        Laya.Tween.to(block, { rotation: 360 }, duration);
        
        // 创建抛物线路径动画
        this.animateParabola(block, startX, startY, midX, midY, endX, endY, duration);
    });
}

/**
 * 执行抛物线动画
 * @param block 方块对象
 * @param startX 起始X坐标
 * @param startY 起始Y坐标
 * @param midX 中点X坐标
 * @param midY 中点Y坐标
 * @param endX 结束X坐标
 * @param endY 结束Y坐标
 * @param duration 动画持续时间
 */
private animateParabola(block: Laya.Sprite, startX: number, startY: number, 
                       midX: number, midY: number, endX: number, endY: number, 
                       duration: number): void {
    let startTime = Laya.Browser.now();
    
    const updatePosition = () => {
        let elapsed = Laya.Browser.now() - startTime;
        let progress = Math.min(elapsed / duration, 1);
        
        if (progress >= 1) {
            // 动画结束
            block.x = endX;
            block.y = endY;
            
            // 播放到达效果（可选）
            this.playArrivalEffect(block);
            
            // 移除并回收方块
            Laya.timer.once(200, this, () => {
                if (block && block.parent) {
                    block.parent.removeChild(block);
                    this.recycleBlock(block);
                }
            });
            
            return;
        }
        
        // 计算贝塞尔曲线位置
        let t = progress;
        let x = (1 - t) * (1 - t) * startX + 2 * (1 - t) * t * midX + t * t * endX;
        let y = (1 - t) * (1 - t) * startY + 2 * (1 - t) * t * midY + t * t * endY;
        
        block.x = x;
        block.y = y;
        
        // 继续下一帧
        Laya.timer.frameOnce(1, this, updatePosition);
    };
    
    updatePosition();
}

/**
 * 播放到达效果
 * @param block 到达的方块
 */
private playArrivalEffect(block: Laya.Sprite): void {
    // 创建缩放效果
    Laya.Tween.to(block, { scaleX: 1.5, scaleY: 1.5 }, 100, null, 
        Laya.Handler.create(this, () => {
            Laya.Tween.to(block, { scaleX: 1, scaleY: 1, alpha: 0 }, 100);
        }));
}
