  showOpt(opt: Opt): void {
    this.playOptAudio(opt);
    this.showCellOpt(opt.cellOptList);
    this.showEffectOpt(opt.effectOptList);
  }

  private playOptAudio(opt: Opt): void {
    if (opt.optType === OptType.Swap || opt.optType === OptType.Crush) {
      AudioUtils.playSwap();
    } else {
      AudioUtils.playClick();
    }
  }

  /**
   * 显示单元格操作
   * @param optList 单元格操作列表
   */
  private showCellOpt(optList: CellOpt[]): void {
    if (!optList || optList.length === 0) return;

    for (const cellOpt of optList) {
      let node = DataManger.findCellNodeByID(cellOpt.id);
      const actions: any[] = [];
      let curTime = 0;

      for (const cmd of cellOpt.cmdList) {
        // 添加延迟
        if (cmd.playTime > curTime) {
          actions.push({
            delay: (cmd.playTime - curTime) * 1000,
          });
        }

        // 处理不同命令
        if (cmd instanceof CellCreate) {
          node = this.getCreateCell(cellOpt, cmd);
          actions.push({
            callback: () => {
              node.alpha = 1; // 设置可见
            },
          });
        } else if (cmd instanceof CellSelect) {
          if (!node) {
            console.log("cellView", node, cellOpt.id);
          }
          // actions.push({
          //   callback: () => {
          const cellView = node as CellView;
          //   const cellView = node.getComponent(CellView) as CellView;
          cellView.setSelect(cmd.status);
          //   },
          // });
        } else if (cmd instanceof CellMoveTo) {
          const targetX = CELL_WIDTH * (cmd.pos.x - 0.5);
          const targetY = CELL_HEIGHT * (cmd.pos.y - 0.5);

          actions.push({
            moveTo: { x: targetX, y: targetY },
            duration: cmd.keepTime * 1000,
          });
        } else if (cmd instanceof CellDie) {
          actions.push({
            callback: () => {
              node.readyDie();
            },
          });
        } else if (cmd instanceof CellShare) {
          actions.push({
            shake: true,
            duration: cmd.keepTime * 1000,
          });
        }

        curTime = cmd.playTime + cmd.keepTime;
      }

      // 执行动作序列
      node.runActions(actions);
    }
  }

  /**
   * 执行动作序列
   * @param target 目标对象
   * @param actions 动作列表
   */
  private runActions(target: Laya.Sprite, actions: any[]): void {
    let ownerTween: Laya.Tween | null = null;
    var hasTask = false;

    for (const action of actions) {
      if (action.delay) {
        // 创建延迟动作
        if (!ownerTween) {
          ownerTween = Laya.Tween.create(target).delay(action.delay);
        } else {
          ownerTween = ownerTween.chain().delay(action.delay);
        }
      } else if (action.moveTo) {
        // 创建移动动作

        if (!ownerTween) {
          ownerTween = Laya.Tween.create(target)
            .to("x", action.moveTo.x)
            .to("y", action.moveTo.y)
            .duration(action.duration);
        } else {
          ownerTween = ownerTween
            .chain()
            .to("x", action.moveTo.x)
            .to("y", action.moveTo.y)
            .duration(action.duration);
        }
      } else if (action.callback) {
        // 创建回调动作

        if (!ownerTween) {
          ownerTween = Laya.Tween.create(target).then(action.callback);
        } else {
          ownerTween = ownerTween.chain().then(action.callback);
        }
      } else if (action.shake) {
        // 创建抖动动作

        if (!ownerTween) {
          ownerTween = Laya.Tween.create(target)
            .to("rotation", 30)
            .duration(action.duration / 6)
            .chain()
            .to("rotation", -60)
            .duration(action.duration / 3)
            .chain()
            .to("rotation", 0)
            .duration(action.duration / 6);
        } else {
          ownerTween = ownerTween
            .chain()
            .to("rotation", 30)
            .duration(action.duration / 6)
            .chain()
            .to("rotation", -60)
            .duration(action.duration / 3)
            .chain()
            .to("rotation", 0)
            .duration(action.duration / 6);
        }
      }
    }
  }

  /**
   * 创建格子视图（只创建CellView大Prefab，元素和障碍物Prefab由CellView管理）
   */
  private getCreateCell(cellOpt: CellOpt, cmd: CellCreate): CellView {
    const cellViewPrefab = DataManger.cellViewPrefab; //CellView大Prefab
    const aniView = cellViewPrefab.create() as CellView;
    aniView.name = CELL_NAME_PREFIX + cellOpt.id;
    const cellView = aniView as CellView;
    if (cmd.zIndex != -1) {
      this.owner.grid.addChildAt(aniView, cmd.zIndex);
    } else {
      this.owner.grid.addChild(aniView);
    }

    cellView.initWithModel(cellOpt);
    aniView.alpha = 0;
    return aniView;
  }

