  updateSelect(pos: Laya.Point): void {
    for (let i = 1; i <= 9; i++) {
      for (let j = 1; j <= 9; j++) {
        const cellView = this.cellViews[i]?.[j];
        if (cellView) {
          const cellViewComp = cellView as CellView;
          if (cellViewComp) {
            cellViewComp.setSelect(pos.x === j && pos.y === i);
          }
        }
      }
    }
  }

  private findViewByModel(model: CellModel): any {
    for (let i = 1; i <= 9; i++) {
      for (let j = 1; j <= 9; j++) {
        const view = this.cellViews[i]?.[j];
        if (view) {
          const cellViewComp = view as CellView;
          if (cellViewComp && cellViewComp.model === model) {
            return { view, x: j, y: i };
          }
        }
      }
    }
    return null;
  }

  getPlayAniTime(changeModels: any[]): number {
    if (!changeModels) return 0;
    let maxTime = 0;
    for (const ele of changeModels) {
      for (const cmd of ele.cmd) {
        const endTime = cmd.playTime + cmd.keepTime;
        if (endTime > maxTime) maxTime = endTime;
      }
    }
    return maxTime;
  }

  getStep(effectsQueue: any[]): number {
    if (!effectsQueue || effectsQueue.length === 0) return 0;
    let maxStep = 0;
    for (const effectCmd of effectsQueue) {
      const step = effectCmd.step || 0;
      if (step > maxStep) maxStep = step;
    }
    return maxStep;
  }

