const { regClass } = Laya;
import { SceneType } from "../../common/baseScene/SceneType";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import { LayerManager } from "../../common/LayerManager";
import SceneManager from "../../common/SceneManager";
import { PlayerDto } from "../../data/dto/PlayerDto";
import { LevelItem } from "../../data/sheetItem/role/LevelItem";
import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import GlobalDataManager from "../../global/GlobalDataManager";
import SheetDataManager from "../../global/SheetDataManager";
import { com } from "../../network/pb/socket";
import RoomWebSocket from "../../network/RoomWebSocket";
import { ComUtil } from "../../utils/ComUtil";
import { VsSceneBase } from "./VsScene.generated";

@regClass('bAKJwT3+QPOPr6nuxv329Q==')
export class VsScene extends VsSceneBase {
    public m_iLayerType: number;
    public m_iPositionType: number;
    private elapsedSeconds: number = 0; // 已经过的秒数
    private countdownSeconds: number = 0; // 倒计时秒数
    private pvpData:any;
    private matchData:any;

    onAwake(): void {
        this.m_iLayerType = LayerManager.M_POP;
        this.m_iPositionType = LayerManager.UP;

        // 移除速度控制UI的创建
    }

    onEnable(): void {
        if (this.btn_back) {
            this.btn_back.on(Laya.Event.CLICK, this, this.setToMainScene);
        }
        Signal.on(GameEvent.EVENT_MATCH_SUCCESS, this, this.onMatchSuccess);
        this.btn_startGame.on(Laya.Event.CLICK, this, this.startGame);
        // 初始化计时显示
        // this.tf_time.text = "匹配中: 00:00";
        this.tf_time.text = GameLanguageMgr.getLanguage(3003, "00","00");
        this.elapsedSeconds = 0;
        this.startTimer();
        this.setMyData();
        // 启动计时器，每秒更新一次
    }

    onOpened(param: any): void {
        console.log(param);
        this.matchData = param;
        this.secondMatch(param);
        // RoomWebSocket.initSocket();
    }

    onDisable(): void {
        this.btn_back.off(Laya.Event.CLICK, this, this.setToMainScene);
        Signal.off(GameEvent.EVENT_MATCH_SUCCESS, this, this.onMatchSuccess);
        // Signal.off("msg_" + com.snake.socket.MessageType.MSG_GAME_MATCH, this, this.onRequestRoomAddr);

        // 清除计时器
        Laya.timer.clear(this, this.updateTimer);
        Laya.timer.clear(this, this.updateCountdown); // 清除倒计时定时器
    }

    private startTimer(): void {
        Laya.timer.loop(1000, this, this.updateTimer);
    }

    private updateTimer(): void {
        this.elapsedSeconds++;
        const minutes = Math.floor(this.elapsedSeconds / 60);
        const seconds = this.elapsedSeconds % 60;

        // 格式化时间显示为 MM:SS
        const minutesStr = minutes.toString().padStart(2, '0');
        const secondsStr = seconds.toString().padStart(2, '0');
        this.tf_time.text = GameLanguageMgr.getLanguage(3003, minutesStr,secondsStr);
    }

    private setToMainScene(): void {
        console.log("this.matchData",this.matchData)
        const cmdId = com.snake.socket.MessageType.MSG_OUT_MATCH;
                    // var cmdId = com.snake.socket.MessageType.MSG_GAME_MATCH;
            var o = com.snake.socket.CS_GAME_MATCH.fromObject({
                ticketId: this.matchData.ticketId,
                point: this.matchData.point,
                id: this.matchData.id,
                roleId: this.matchData.roleId,
            });
        RoomWebSocket.sendData(cmdId,o);
        RoomWebSocket.closeConnect();
        SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
    }

    private setMyData() {
        let playerDto: PlayerDto = GlobalDataManager.playerDto;
        if (!playerDto) return;
        this.tf_roleName.text = ComUtil.fitTextToLabel(playerDto.name, this.tf_roleName);
        this.playerIcon.dataSource = playerDto;
        playerDto.needTip = true;
        this.tf_roleScore.text = GameLanguageMgr.getLanguage(3000, playerDto.elsMMR);
    }

    /**
     * 第二次发给房间的匹配请求
     * @param matchData 
     */
    private secondMatch(matchData: com.snake.socket.CS_GAME_MATCH) {
        //连接房间socket
        if (RoomWebSocket.getIsConnect()) {
            var cmdId = com.snake.socket.MessageType.MSG_GAME_MATCH;
            var o = com.snake.socket.CS_GAME_MATCH.fromObject({
                ticketId: GlobalDataManager.MathchData.ticketId,
                point: GlobalDataManager.MathchData.point,
                id: GlobalDataManager.MathchData.id,
                roleId: GlobalDataManager.MathchData.roleId,
            });
            RoomWebSocket.sendData(cmdId, o);
        } else {
            RoomWebSocket.initSocket();
        }
    }

    private onMatchSuccess(msgBody: com.snake.socket.SC_GAME_MATCH_NOTICE) {
        console.log("匹配成功", msgBody);
        Laya.timer.clear(this, this.updateTimer);
        this.tf_time.text = GameLanguageMgr.getLanguage(3002);
        this.btn_back.visible = false;  
        // this.
        this.pvpData = msgBody;
        let enemyData = msgBody.players.find((item) => item.roleId != GlobalDataManager.playerDto.pid);
        if(enemyData){
            this.showEnemyData(enemyData)
        }
        // this.btn_startGame.visible = true;
        // 开始5秒倒计时
        this.countdownSeconds = 3;
        this.tf_time.text = GameLanguageMgr.getLanguage(3001, this.countdownSeconds);
        this.tf_time.visible = true;
        // 启动倒计时定时器
        Laya.timer.loop(1000, this, this.updateCountdown);
    }

    private startGame(){
        SceneManager.setCurrentScene(SceneType.M_SCENE_PVP_TETRIS,this.pvpData);
    }

    private updateCountdown(): void {
        this.countdownSeconds--;
        if (this.countdownSeconds > 0) {
            this.tf_time.text = GameLanguageMgr.getLanguage(3001, this.countdownSeconds);
        } else {
            // 倒计时结束，清除定时器并跳转场景
            Laya.timer.clear(this, this.updateCountdown);
            SceneManager.setCurrentScene(SceneType.M_SCENE_PVP_TETRIS,this.pvpData);
        }
    }

    private showEnemyData(enemyData: com.snake.socket.PlayerObject) {
        this.img_question.visible = false;
        this.tf_roleName2.text = enemyData.userName;
        this.tf_roleScore2.text = GameLanguageMgr.getLanguage(3000, enemyData.elsMMR);
        this.playerIcon2.dataSource = enemyData;
        // this.tf_lv2.text = `${enemyData.lv}`;
        // let levelItem: LevelItem = SheetDataManager.getLevelById(enemyData.lv);
        // this.prog_exp2.value = enemyData.exp / levelItem.needExp;
    }
}
