const { regClass } = Laya;

@regClass('9K8tC6MuTIOTvAk9y2ztcg==')
export class WebTokenListItem2 extends WebTokenListItem2Base {
    isAddEvent: boolean;
    public set dataSource(value: any) {
        super.dataSource = value;
        if (!value) {
            this.visible = false;
            return;
        }
        const index = (this.parent?.parent as Laya.List)?.array?.indexOf(value) ?? 0;
        this.img_bg.visible = index % 2 === 1;
        if(value){
            // globalDataManager.tokenData里面筛选出symbolId与value.ticketType相等的项目
            let tokenData = AssetManager.getTokenDataBySyId(value)
            if(tokenData){
                this.tf_data.text = tokenData.symbol;
                this.img_coin.skin = GameResourceManager.getCurrencyIcon(tokenData.symbol)
            }else{
                this.visible = false
            }

        }
    }

    onDisable(): void {
    }

    private onChange(isSelect:boolean){
        if(isSelect){
            this.selectImg.visible = true;
            // this.tf_data.color = "#ffffff";
        }else{
            // this.tf_data.color = "#357cc0";
            this.selectImg.visible = false;
        }
    }
}
