// GameModel.ts

import CellModel from "./CellModel";
import { GRID_HEIGHT, GRID_WIDTH, CELL_TYPE_CONFIGS, OBSTACLE_CONFIGS, CELL_STATUS, ANITIME, CELL_TYPE, CELL_BASE_NUM, CELL_HEIGHT, CELL_WIDTH } from "./ConstValue";
import DataManger from "./DataManger";
import { EventBus } from "./EventBus";
import Opt, { CellSelect, OptType, CellMoveTo, CellCreate, EffectRowBomb, EffectColBomb, CellShare, CellDie, EffectCrush } from "./OptCmd";


/**
 * 游戏模型
 */
export default class GameModel {
  cells: CellModel[][]; // 网格单元格
  lastPos: Laya.Point | null; // 上次点击位置
  cellTypeNum: number; // 单元格类型数量
  cellCreateType: number[]; // 单元格创建类型

  constructor() {
    this.lastPos = null;
    this.cellTypeNum = 5;
    this.cellCreateType = [];
  }

  /**
   * 初始化游戏（查表驱动元素类型和障碍物）
   * @param cellTypeNum 单元格类型数量
   * @param obstacleMap 可选，障碍物分布配置（如关卡配置）
   */
  init(cellTypeNum: number, obstacleMap?: { [key: string]: string }) {
    this.cells = [];
    this.setCellTypeNum(cellTypeNum || this.cellTypeNum);

    // 初始化网格
    for (let y = 1; y <= GRID_HEIGHT; y++) {
      this.cells[y] = [];
      for (let x = 1; x <= GRID_WIDTH; x++) {
        var imgBg = new Laya.Image();
        imgBg.skin = "resources/texture/450/img_gezi.png";
        var gap = 2;
        imgBg.size(CELL_WIDTH - gap, CELL_HEIGHT - gap);
        imgBg.pivot((CELL_WIDTH - gap) / 2, (CELL_HEIGHT - gap) / 2);
        imgBg.pos(CELL_WIDTH * (x - 0.5), CELL_HEIGHT * (y - 0.5));
        DataManger.grid.addChild(imgBg);

        const cell = new CellModel();
        // 1. 元素类型查CELL_TYPE_CONFIGS
        const normalTypes = CELL_TYPE_CONFIGS.filter((cfg) => cfg.type <= 6);
        const type =
          normalTypes[Math.floor(Math.random() * normalTypes.length)].type;
        cell.setType(type);
        cell.setXY(x, y);
        cell.setStartXY(x, y);
        // 2. 障碍物查OBSTACLE_CONFIGS
        if (obstacleMap) {
          const key = `${x},${y}`;
          if (obstacleMap[key]) {
            const obsCfg = OBSTACLE_CONFIGS.find(
              (cfg) => cfg.type === obstacleMap[key]
            );
            if (obsCfg) {
              cell.obstacle = { ...obsCfg };
            }
          }
        }
        this.cells[y][x] = cell;
      }
    }

    // 填充网格并确保初始无匹配
    for (let y = 1; y <= GRID_HEIGHT; y++) {
      for (let x = 1; x <= GRID_WIDTH; x++) {
        let flag = true;
        while (flag) {
          flag = false;
          this.cells[y][x].setType(this.getRandomCellType());
          const result = this.checkPoint(x, y)[0] as Laya.Point[];
          if (result.length > 2) {
            flag = true;
          }
          this.cells[y][x].setXY(x, y);
          this.cells[y][x].setStartXY(x, y);
        }
      }
    }
  }

  /**
   * 带方向检查匹配
   * @param x 列坐标
   * @param y 行坐标
   * @param direction 检查方向
   * @returns 匹配点列表
   */
  checkWithDirection(
    x: number,
    y: number,
    direction: Laya.Point[]
  ): Laya.Point[] {
    const queue: Laya.Point[] = [];
    const vis: boolean[] = [];
    vis[x + y * 9] = true;
    queue.push(new Laya.Point(x, y));
    let front = 0;

    while (front < queue.length) {
      const point = queue[front++];
      const cellModel = this.cells[point.y][point.x];
      if (!cellModel) continue;

      for (const dir of direction) {
        const tmpX = point.x + dir.x;
        const tmpY = point.y + dir.y;

        if (
          tmpX < 1 ||
          tmpX > 9 ||
          tmpY < 1 ||
          tmpY > 9 ||
          vis[tmpX + tmpY * 9] ||
          !this.cells[tmpY][tmpX]
        )
          continue;

        if (cellModel.type === this.cells[tmpY][tmpX].type) {
          vis[tmpX + tmpY * 9] = true;
          queue.push(new Laya.Point(tmpX, tmpY));
        }
      }
    }
    return queue;
  }

  /**
   * 检查点匹配
   * @param x 列坐标
   * @param y 行坐标
   * @returns [匹配点列表, 新状态, 类型]
   */
  checkPoint(x: number, y: number): [Laya.Point[], string, number] {
    const rowResult = this.checkWithDirection(x, y, [
      new Laya.Point(1, 0),
      new Laya.Point(-1, 0),
    ]);
    const colResult = this.checkWithDirection(x, y, [
      new Laya.Point(0, -1),
      new Laya.Point(0, 1),
    ]);

    let newCellStatus = "";
    if (rowResult.length >= 5 || colResult.length >= 5) {
      newCellStatus = CELL_STATUS.BIRD;
    } else if (rowResult.length >= 3 && colResult.length >= 3) {
      newCellStatus = CELL_STATUS.WRAP;
    } else if (rowResult.length >= 4) {
      newCellStatus = CELL_STATUS.ROW;
    } else if (colResult.length >= 4) {
      newCellStatus = CELL_STATUS.COLUMN;
    }

    let result: Laya.Point[] = [];
    if (colResult.length >= 3) {
      result = colResult;
    }
    if (rowResult.length >= 3) {
      result = this.unionPoints(
        [result, rowResult],
        (a: Laya.Point, b: Laya.Point) => a.x === b.x && a.y === b.y
      );
    }
    if (!this.cells[y][x]) {
      console.log("cells[y][x] = ", this.cells[y][x], "y:" + y, "x:" + x);
    }
    return [result, newCellStatus, this.cells[y][x].type];
  }

  private unionPoints(
    arrays: Laya.Point[][],
    comparator: (a: Laya.Point, b: Laya.Point) => boolean
  ): Laya.Point[] {
    const result: Laya.Point[] = [];
    const keySet = new Set<string>();

    for (const array of arrays) {
      for (const point of array) {
        const key = `${point.x},${point.y}`;

        // 如果该坐标点已处理过，跳过
        if (keySet.has(key)) continue;
        keySet.add(key);

        // 添加到结果（使用比较器检查重复）
        if (!result.some((existing) => comparator(existing, point))) {
          result.push(point);
        }
      }
    }

    return result;
  }

  /**
   * 选择单元格
   * @param pos 位置
   * @returns 操作对象
   */
  selectCell(pos: Laya.Point): Opt {
    console.log("pos = ", pos);
    const opt = new Opt();
    const curClickCell = this.cells[pos.y][pos.x];

    // 如果当前格子有障碍物，禁止选中和交换
    if (curClickCell.obstacle) {
      // 可选：给出提示或动画
      return opt;
    }

    // 第一次点击
    if (this.lastPos === null) {
      this.lastPos = pos;
      opt.addCellOptCmd(curClickCell, new CellSelect(true));
      opt.optType = OptType.Click;
      return opt;
    }

    const lastPos = this.lastPos;
    const delta = Math.abs(pos.x - lastPos.x) + Math.abs(pos.y - lastPos.y);
    const lastClickCell = this.cells[lastPos.y][lastPos.x];

    // 如果目标格子有障碍物，禁止交换
    if (lastClickCell.obstacle) {
      // 可选：给出提示或动画
      this.lastPos = null;
      return opt;
    }

    console.log("delta = ", delta);
    // 非相邻格子
    if (delta !== 1) {
      this.lastPos = pos;
      opt.addCellOptCmd(lastClickCell, new CellSelect(false));
      opt.addCellOptCmd(curClickCell, new CellSelect(true));
      opt.optType = OptType.Click;
      return opt;
    }

    // 交换单元格
    this.exchangeCell(lastPos, pos);
    const result1 = this.checkPoint(pos.x, pos.y)[0] as Laya.Point[];
    const result2 = this.checkPoint(lastPos.x, lastPos.y)[0] as Laya.Point[];
    opt.curTime = 0;

    const isCanBomb =
      (curClickCell.status !== CELL_STATUS.NORMAL &&
        lastClickCell.status !== CELL_STATUS.NORMAL) ||
      curClickCell.status === CELL_STATUS.BIRD ||
      lastClickCell.status === CELL_STATUS.BIRD;

    opt.addCellOptCmd(lastClickCell, new CellSelect(false));

    // 不会消除的情况
    if (result1.length < 3 && result2.length < 3 && !isCanBomb) {
      this.exchangeCell(lastPos, pos);
      opt.addCellOptCmd(curClickCell, new CellMoveTo(lastPos));
      opt.addCellOptCmd(lastClickCell, new CellMoveTo(pos));
      opt.addTime(ANITIME.TOUCH_MOVE);
      opt.addCellOptCmd(curClickCell, new CellMoveTo(pos));
      opt.addCellOptCmd(lastClickCell, new CellMoveTo(lastPos));
      this.lastPos = null;
      opt.addTime(ANITIME.TOUCH_MOVE);
      opt.optType = OptType.Swap;
      // 步数-1事件（去掉，交换失败不扣步数）
      // EventBus.getInstance().emit("playerMove");
    }
    // 会消除的情况
    else {
      this.lastPos = null;
      opt.addCellOptCmd(curClickCell, new CellMoveTo(lastPos));
      opt.addCellOptCmd(lastClickCell, new CellMoveTo(pos));
      const checkPoint = [pos, lastPos];
      opt.addTime(ANITIME.TOUCH_MOVE);
      this.processCrush(opt, checkPoint);
      opt.optType = OptType.Crush;
      // 步数-1事件（只在交换成功时emit）
      EventBus.getInstance().emit("playerMove");
    }

    return opt;
  }

  /**
   * 处理消除
   * @param opt 操作对象
   * @param checkPoint 检查点
   */
  processCrush(opt: Opt, checkPoint: Laya.Point[]): void {
    let cycleCount = 0;
    while (checkPoint.length > 0) {
      let bombModels: CellModel[] = [];
      let hasCrush = false;
      let eliminateCount = 0;
      let isSpecial = false;

      // 特殊消除处理
      if (cycleCount === 0 && checkPoint.length === 2) {
        const pos1 = checkPoint[0];
        const pos2 = checkPoint[1];
        const model1 = this.cells[pos1.y][pos1.x];
        const model2 = this.cells[pos2.y][pos2.x];

        if (
          model1.status === CELL_STATUS.BIRD ||
          model2.status === CELL_STATUS.BIRD
        ) {
          hasCrush = true;
          if (model1.status === CELL_STATUS.BIRD) {
            model1.type = model2.type;
            bombModels.push(model1);
          } else {
            model2.type = model1.type;
            bombModels.push(model2);
          }
        }
      }

      // 检查所有点
      for (const pos of checkPoint) {
        console.log("pos = ", pos, this.cells);
        if (!this.cells[pos.y][pos.x]) {
          continue;
        }
        const [result, newCellStatus, newCellType] = this.checkPoint(
          pos.x,
          pos.y
        );

        if (result.length < 3) continue;

        eliminateCount += result.length;

        // 处理匹配的单元格
        for (const point of result) {
          hasCrush = true;
          const model = this.cells[point.y][point.x];
          this.crushCell(opt, point.x, point.y, false, cycleCount);
          if (model.status !== CELL_STATUS.NORMAL) {
            bombModels.push(model);
          }
        }

        // 创建新单元格
        this.createNewCell(opt, pos, newCellStatus, newCellType);

        // 判断特殊消除
        if (newCellStatus && newCellStatus !== "normal") isSpecial = true;
      }

      // 处理爆炸效果
      this.processBomb(opt, bombModels, cycleCount);

      if (hasCrush && eliminateCount > 0) {
        // 消除事件
        EventBus.getInstance().emit("eliminate", eliminateCount, isSpecial);
      }

      if (hasCrush) {
        opt.addTime(ANITIME.DIE);
        checkPoint = this.down(opt);
      } else {
        checkPoint = [];
      }

      cycleCount++;
    }
  }

  /**
   * 创建新单元格
   * @param opt 操作对象
   * @param pos 位置
   * @param status 状态
   * @param type 类型
   * @returns 新单元格模型
   */
  createNewCell(
    opt: Opt,
    pos: Laya.Point,
    status: string,
    type: number
  ): CellModel | null {
    if (!status) return null;

    if (status === CELL_STATUS.BIRD) {
      type = CELL_TYPE.BIRD;
    }

    const model = new CellModel();
    this.cells[pos.y][pos.x] = model;
    model.setType(type);
    model.setStartXY(pos.x, pos.y);
    model.setXY(pos.x, pos.y);
    model.setStatus(status);
    opt.addCellOptCmd(model, new CellCreate());

    return model;
  }
  // 下落处理函数 (LayaAir版本，保持先列后行遍历顺序)
  down(opt: Opt): any[] {
    let newCheckPoint = [];
    // 保持先遍历列(宽度方向)
    for (let col = 1; col <= GRID_WIDTH; col++) {
      // 在每一列中，保持从下向上遍历行(底部到顶部)
      for (let row = GRID_HEIGHT; row >= 1; row--) {
        // 1. 目标格子有障碍物时，不能下落/补充
        if (this.cells[row][col] && this.cells[row][col].obstacle) {
          continue;
        }
        // 2. 只对空格子做下落
        if (this.cells[row][col] == null) {
          let found = false;
          // 3. 从上往下找第一个没有障碍物的普通元素，遇到障碍物break
          for (let scanRow = row - 1; scanRow >= 1; scanRow--) {
            if (this.cells[scanRow][col]) {
              if (this.cells[scanRow][col].obstacle) {
                // 遇到障碍物，断开，不再往上找
                break;
              } else {
                // 普通元素可以下落
                this.cells[row][col] = this.cells[scanRow][col];
                this.cells[scanRow][col] = null;
                newCheckPoint.push(this.cells[row][col]);
                this.cells[row][col].setXY(col, row);
                opt.addCellOptCmd(
                  this.cells[row][col],
                  new CellMoveTo(new Laya.Point(col, row))
                );
                found = true;
                break;
              }
            }
          }
          // 4. 如果上面没有可下落的元素，则补充新元素
          if (!found) {
            this.cells[row][col] = new CellModel();
            const cellType = this.getRandomCellType();
            this.cells[row][col].setType(cellType);
            // 优化：新元素动画起点为当前行以上最近的障碍物位置，否则为-1
            let startRow = -1;
            for (let scan = row - 1; scan >= 1; scan--) {
              if (this.cells[scan][col] && this.cells[scan][col].obstacle) {
                startRow = scan;
                break;
              }
            }
            var zIndex = -1;
            if (startRow != -1) {
              //获取 col,startRow 的障碍的层级
              const cellOpt = this.cells[startRow][col];
              let node = DataManger.findCellNodeByID(cellOpt.id);
              if (node) {
                //获取node在父容器里的显示层级
                zIndex = node.parent.getChildIndex(node);
              }
            }
            this.cells[row][col].setStartXY(col, startRow);
            this.cells[row][col].setXY(col, row);
            var createCmd = new CellCreate();
            createCmd.zIndex = zIndex;
            opt.addCellOptCmd(this.cells[row][col], createCmd);
            opt.addCellOptCmd(
              this.cells[row][col],
              new CellMoveTo(new Laya.Point(col, row))
            );
            newCheckPoint.push(this.cells[row][col]);
          }
        }
      }
    }
    opt.addTime(ANITIME.TOUCH_MOVE + ANITIME.DOWN_DELAY);
    return newCheckPoint;
  }

  /**
   * 清除命令
   */
  cleanCmd(): void {
    for (let y = 1; y <= GRID_HEIGHT; y++) {
      for (let x = 1; x <= GRID_WIDTH; x++) {
        if (this.cells[y][x]) {
          this.cells[y][x].cmd = [];
        }
      }
    }
  }

  /**
   * 交换单元格
   * @param pos1 位置1
   * @param pos2 位置2
   */
  exchangeCell(pos1: Laya.Point, pos2: Laya.Point): void {
    const tmpModel = this.cells[pos1.y][pos1.x];
    this.cells[pos1.y][pos1.x] = this.cells[pos2.y][pos2.x];
    this.cells[pos1.y][pos1.x].x = pos1.x;
    this.cells[pos1.y][pos1.x].y = pos1.y;

    this.cells[pos2.y][pos2.x] = tmpModel;
    this.cells[pos2.y][pos2.x].x = pos2.x;
    this.cells[pos2.y][pos2.x].y = pos2.y;
  }

  /**
   * 查找一组可交换且能消除的格子
   * @returns [Laya.Point, Laya.Point] | null
   */
  findHintSwap(): [Laya.Point, Laya.Point] | null {
    for (let y = 1; y <= GRID_HEIGHT; y++) {
      for (let x = 1; x <= GRID_WIDTH; x++) {
        const dirs = [
          { dx: 1, dy: 0 },
          { dx: 0, dy: 1 },
        ];
        for (const dir of dirs) {
          const nx = x + dir.dx;
          const ny = y + dir.dy;
          if (nx > GRID_WIDTH || ny > GRID_HEIGHT) continue;
          // 跳过障碍物
          if (this.cells[y][x]?.obstacle || this.cells[ny][nx]?.obstacle)
            continue;
          // 模拟交换
          this.exchangeCell(new Laya.Point(x, y), new Laya.Point(nx, ny));
          const r1 = this.checkPoint(x, y)[0] as Laya.Point[];
          const r2 = this.checkPoint(nx, ny)[0] as Laya.Point[];
          // 只要有一方能消除
          if (r1.length >= 3 || r2.length >= 3) {
            // 还原
            this.exchangeCell(new Laya.Point(x, y), new Laya.Point(nx, ny));
            return [new Laya.Point(x, y), new Laya.Point(nx, ny)];
          }
          // 还原
          this.exchangeCell(new Laya.Point(x, y), new Laya.Point(nx, ny));
        }
      }
    }
    return null;
  }

  /**
   * 设置单元格类型数量
   * @param num 类型数量
   */
  setCellTypeNum(num: number): void {
    this.cellTypeNum = num;
    this.cellCreateType = [];
    if (this.cellTypeNum > CELL_BASE_NUM) {
        console.error("cellTypeNum > CELL_BASE_NUM");//传入类型，必须小于最大类型数量
    }
    // 填充类型数组
    for (let i = 1; i <= CELL_BASE_NUM; i++) {
      this.cellCreateType.push(i);
    }

    // 随机打乱顺序
    for (let i = 0; i < this.cellCreateType.length; i++) {
      const index = Math.floor(Math.random() * (CELL_BASE_NUM - i)) + i;
      [this.cellCreateType[i], this.cellCreateType[index]] = [
        this.cellCreateType[index],
        this.cellCreateType[i],
      ];
    }
  }

  /**
   * 获取随机单元格类型
   * @returns 随机类型
   */
  getRandomCellType(): number {
    const index = Math.floor(Math.random() * this.cellTypeNum);
    return this.cellCreateType[index];
  }

  /**
   * 处理爆炸效果
   * @param opt 操作对象
   * @param bombModels 爆炸模型
   * @param cycleCount 循环计数
   */
  processBomb(opt: Opt, bombModels: CellModel[], cycleCount: number): void {
    while (bombModels.length > 0) {
      const newBombModel: CellModel[] = [];

      for (const model of bombModels) {
        if (model.status === CELL_STATUS.ROW) {
          // 行消除
          for (let x = 1; x <= GRID_WIDTH; x++) {
            if (this.cells[model.y][x]) {
              if (this.cells[model.y][x].status !== CELL_STATUS.NORMAL) {
                newBombModel.push(this.cells[model.y][x]);
              }
              this.crushCell(opt, x, model.y, false, cycleCount);
            }
          }
          opt.addEffectOptList(
            new EffectRowBomb(new Laya.Point(model.x, model.y))
          );
        } else if (model.status === CELL_STATUS.COLUMN) {
          // 列消除
          for (let y = 1; y <= GRID_HEIGHT; y++) {
            if (this.cells[y][model.x]) {
              if (this.cells[y][model.x].status !== CELL_STATUS.NORMAL) {
                newBombModel.push(this.cells[y][model.x]);
              }
              this.crushCell(opt, model.x, y, false, cycleCount);
            }
          }
          opt.addEffectOptList(
            new EffectColBomb(new Laya.Point(model.x, model.y))
          );
        } else if (model.status === CELL_STATUS.WRAP) {
          // 包裹消除
          for (let y = 1; y <= GRID_HEIGHT; y++) {
            for (let x = 1; x <= GRID_WIDTH; x++) {
              const delta = Math.abs(model.x - x) + Math.abs(model.y - y);
              if (this.cells[y][x] && delta <= 2) {
                if (this.cells[y][x].status !== CELL_STATUS.NORMAL) {
                  newBombModel.push(this.cells[y][x]);
                }
                this.crushCell(opt, x, y, false, cycleCount);
              }
            }
          }
        } else if (model.status === CELL_STATUS.BIRD) {
          // 鸟消除
          let crushType = model.type;
          if (crushType === CELL_TYPE.BIRD) {
            crushType = this.getRandomCellType();
          }

          opt.addTime(ANITIME.DIE_SHAKE);
          for (let y = 1; y <= GRID_HEIGHT; y++) {
            for (let x = 1; x <= GRID_WIDTH; x++) {
              if (this.cells[y][x] && this.cells[y][x].type === crushType) {
                if (this.cells[y][x].status !== CELL_STATUS.NORMAL) {
                  newBombModel.push(this.cells[y][x]);
                }
                this.crushCell(opt, x, y, true, cycleCount);
              }
            }
          }
        }
      }

      if (bombModels.length > 0) {
        opt.addTime(ANITIME.BOMB_DELAY);
      }

      bombModels = newBombModel;
    }
  }

  /**
   * 消除单元格
   * @param opt 操作对象
   * @param x 列坐标
   * @param y 行坐标
   * @param needShake 是否需要抖动
   * @param step 步骤
   */
  crushCell(
    opt: Opt,
    x: number,
    y: number,
    needShake: boolean,
    step: number
  ): void {
    const model = this.cells[y][x];
    if (!model) return;

    // 在消除、下落等逻辑中，遇到blockType为block的障碍物不能下落/消除
    if (model.hasObstacle() && model.obstacle.blockType === "block") {
      console.log(`[消除跳过] 位置 y: ${y}, x: ${x} 是障碍物，跳过消除`);
      return;
    }

    if (needShake) {
      opt.addCellOptCmd(model, new CellShare());
    }

    opt.addCellOptCmd(model, new CellDie());
    opt.addEffectOptList(
      new EffectCrush(new Laya.Point(model.x, model.y), step)
    );
    this.cells[y][x] = null;
    console.log("===  消除 y: ", model.y, "x:", model.x);
  }

  /**
   * 获取初始操作
   * @returns 初始操作对象
   */
  getInitOpt(): Opt {
    const opt = new Opt();
    for (let y = 1; y <= GRID_HEIGHT; y++) {
      for (let x = 1; x <= GRID_WIDTH; x++) {
        opt.addCellOptCmd(this.cells[y][x], new CellCreate());
      }
    }
    return opt;
  }
}
