    /**
     * 蛇的运动更新方法
     * @param dt 时间增量（单位：秒），每帧经过的时间
     */
    public move(dt: number, isLogicSnake: boolean, hasConfirmed: boolean, needMove: boolean): void {
        if (isLogicSnake) {
            if (hasConfirmed) {
                //如果收到确认帧，真实运行
                if (
                    this.dieRuningFrame != 0 &&
                    this.isViewReadyDie && //视图蛇已经死亡
                    FrameSyncManager.clientRuningFrame > this.dieRuningFrame + 10 &&
                    !this.isLogicReadyDie &&
                    this.isAlive(true) //逻辑蛇没有死
                ) {
                    var str =
                        Quick.GetLogTime +
                        " Snake DIE " +
                        this.tag.roleId +
                        " ==== 死亡恢复: clientRuningFrame: " +
                        FrameSyncManager.clientRuningFrame +
                        ", dieRuningFrame: " +
                        this.dieRuningFrame;
                    console.warn(str);
                    // if (GameSetting.Debug == 2) NoticeMgr.notice(str);
                    this.relive();
                    this.dieRuningFrame = 0;
                }

                var now = Laya.Browser.now();

                if (
                    this.logicDieTime != 0 &&
                    this.isLogicReadyDie && //逻辑蛇已经死亡
                    now > this.logicDieTime + 8000 &&
                    this.isAlive(true) //逻辑蛇没有死
                ) {
                    var str =
                        Quick.GetLogTime +
                        " Snake DIE " +
                        this.tag.roleId +
                        " ==== 死亡异常: now: " +
                        TimeUtil.getTimeByMs(now) +
                        ", logicDieTime: " +
                        TimeUtil.getTimeByMs(this.logicDieTime) +
                        ", clientRuningFrame: " +
                        FrameSyncManager.clientRuningFrame +
                        ", logicDieRuningFrame: " +
                        this.logicDieRuningFrame;
                    console.warn(str);
                    if (GameSetting.vType == 0) Quick.alertYes(str);
                }
            }
            this.logicSnake.move(dt, hasConfirmed, needMove);
        } else {
            this.viewSnake.move(dt, hasConfirmed, needMove);
            this.updateOther();
        }
    }

