    addKill(addKillNum: number) {
        if (this.tag) this.tag.kills += addKillNum;
        // var addKillNum = 1;
        // this.kill += addKillNum;//自己没有死，才能给别人加人头
        if (this.isSelf) {
            var soundKey; // 使用模板字符串生成键名
            if (this.tag.kills <= 5) {
                soundKey = `soundName_kill_${this.tag.kills}`; // 使用模板字符串生成键名
            } else if (this.tag.kills < 8) {
                soundKey = `soundName_kill_t_3`;
            } else if (this.tag.kills < 10) {
                soundKey = `soundName_kill_t_5`;
            } else {
                soundKey = `soundName_kill_t_8`;
            }
            if ((SoundMgr as any)[soundKey]) {
                SoundMgr.playSoundByName((SoundMgr as any)[soundKey]);
            } else {
                console.warn(`音效 ${soundKey} 不存在`);
            }
            this.getHead(false).node.showDamageLabelDetailDelay(addKillNum, 100, true);
        }
    }

    // isSend = false;
