    isLogicReadyDie = false;
    private isStartShineed: boolean = false; // 是否开始闪了
    private isShineed: boolean = false; // 是否闪过了
    isConfirmDied: boolean = false; // 是否确认死亡了

    /**
     * 死亡时的运行帧
     */
    dieRuningFrame: number = 0;
    /**
     * 逻辑蛇死亡时的运行帧
     */
    logicDieRuningFrame: number = 0;
    /**
     * 逻辑死亡时的时间
     */
    logicDieTime: number = 0;
    sendDie(isLogicSnake: boolean) {
        this.isLogicReadyDie = true;
        var now = Laya.Browser.now();

        console.warn(
            `Snake DIE ${this.tag.roleId} `,
            "sendDie now: " + now,
            this.logicDieTime,
            "clientRuningFrame: " + FrameSyncManager.clientRuningFrame,
            this.logicDieRuningFrame,
            this.getCollisionHeadPosition(isLogicSnake)
        );
        this.logicDieTime = now;
        this.logicDieRuningFrame = FrameSyncManager.clientRuningFrame;
        this.setIsStop(true, true);
    }
    readyDie() {
        console.warn(
            Quick.GetLogTime + ` Snake DIE ${this.tag.roleId} `,
            this.isStartShineed,
            "readyDie " + FrameSyncManager.clientRuningFrame,
            this.dieRuningFrame
        );
        if (this.isStartShineed) return;
        this.dieRuningFrame = FrameSyncManager.clientRuningFrame + 1;
        this.isStartShineed = true;
        this.isViewReadyDie = true;
        this.isShineed = false;
        this.setIsStop(true, false);
        // this.viewSnake.gotoDiePos();

        this.startShine(); // TODO:: 可能根据实际显示效果，后续优化死亡后效果
    }
    maxShineTime = 2000;

    startShine() {
        console.log(`Snake ${this.tag.roleId} `, "startShine");
        Laya.timer.clear(this, this.shine);
        Laya.timer.frameLoop(5, this, this.shine);
        Laya.timer.once(this.maxShineTime, this, this.haveShined);
    }

    public shine(dt: number): void {
        this.viewSnake.shine(dt);
        if (this.logicSnake) this.logicSnake.shine(dt);
    }
    haveShined() {
        console.log(`Snake ${this.tag.roleId} `, "haveShined");
        this.isStartShineed = false;
        this.isShineed = true;
        this.stopShine();
        // // TODO:: 暂时客户端让它死亡
        //     this.die();
        if (this.isConfirmDied) {
            //只有pve闪过后，调用die()
            //收到确认死亡了，则开始死亡
            this.die();
        }
    }
    stopShine() {
        console.log(`Snake ${this.tag.roleId} `, "stopShine");
        this.viewSnake.show();
        if (this.logicSnake) this.logicSnake.show();
        Laya.timer.clear(this, this.shine);
    }

    relive() {
        console.log(`Snake ${this.tag.roleId} `, "relive", "this.isConfirmReadyDie: " + this.isLogicReadyDie);
        // this.stop = false; //取消停止状态
        this.setIsStop(false, false);
        // this.setIsStop(false, true);
        this.isViewReadyDie = false;
        // this.isLogicReadyDie = false;
        this.setIsSend(false, false); //视图蛇取消发送状态
        // this.setIsSend(false, true); //逻辑蛇取消发送状态
        this.stopShine(); //取消闪动
    }

    confirmDie() {
        console.log(`Snake ${this.tag.roleId} `, "confirmDie", "this.isShineed: " + this.isShineed);
        // if (this.isShineed) {
        //如果已经闪过了
        this.stopShine();
        this.die();
        // } else {
        //     // 没有闪过的话，先保存状态；
        //     this.isConfirmDied = true;
        //     this.clientSnake.setAlive(false);
        //     if (this.serverSnake) this.serverSnake.setAlive(false);
        // }
    }

    die() {
        console.log(`Snake ${this.tag.roleId} has died.`);
        this.viewSnake.setAlive(false);
        if (this.logicSnake) this.logicSnake.setAlive(false);

        if (!this.isSelf) {
            SnakeManager.getInstance().removeSnake(this.tag.roleId);
        } else {
            this.viewSnake.setGray(true);
            if (this.logicSnake) this.logicSnake.setGray(true);
            SoundMgr.playSoundByName(SoundMgr.soundName_kill_die);
            // Laya.timer.frameLoop(5, this, this.shine);
            Laya.timer.once(1000, this, this.goMatchEnd);
        }
    }

    goMatchEnd() {
        if (MatchModel.matchDto.matchType == EnumMatch.MATCH_TYPE_PVE) {
            FrameAiManager.onPveEnd();
        } else {
            SnakeManager.getInstance().removeSnake(this.tag.roleId);
            MatchModel.onMockMatchEnd();
        }
    }

