@regClass('y+nP/lRrQVef9uttVJ0rDw==')
export class MatchEndView extends MatchEndViewBase {
    public m_strName: string = "我是OpenSceneRuntime";
    public m_iLayerType: number = LayerManager.M_PANEL;
    public m_iPositionType: number = LayerManager.CENTER;

    private roomGameOverPush: com.snake.socket.SC_BATTLE_END;
    private arenaType: number;
    onEnable(): void {
        Signal.on("msg_" + com.snake.socket.MessageType.MSG_AI_END, this, this.onAiEnd);
        SoundMgr.playSoundByName(SoundMgr.soundName_win);
        this.btn_fightAgain.on(Laya.Event.CLICK, this, this.goFightAgain);
        this.btn_home.on(Laya.Event.CLICK, this, this.setToAirdropScene);
        this.btn_help.on(Laya.Event.CLICK, this, this.onNext);
        //EVENT ::打开比赛奖励界面
        PlatFormManager.sendCustumEvent(43);
    }

    private onHelp(): void {
        Quick.commTipWithYes(GameLanguageMgr.getLanguage("HELP"));
    }
    private onNext(): void {
        this.setToAirdropScene();
    }

    private setToAirdropScene(): void {
        // Laya.Browser.window.location.reload();
        SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
    }

    public setOpenData(data: any[]) {
        this.arenaType = data[0];

        this.list_reward.visible = false;
        var itemDtos: com.snake.socket.ItemObject[];
        var tokens: string[];
        this.list_reward.vScrollBarSkin = "";

        this.roomGameOverPush = MatchModel.msgEndbody;
        this.tf_rank.text = `${this.roomGameOverPush.rank}`;
        this.tf_score.text = `${this.roomGameOverPush.score}`;

        const fontClip_kill = this.fontClip_kill.getComponent(NumberIncrement);
        fontClip_kill.startIncrement(this.roomGameOverPush.kills, 1, 1);

        const fontClip_length = this.fontClip_length.getComponent(NumberIncrement);
        fontClip_length.startIncrement(this.roomGameOverPush.length, 1, 1);

        const fontClip_challengeDuration = this.fontClip_challengeDuration.getComponent(NumberIncrement);
        fontClip_challengeDuration.startIncrement(this.roomGameOverPush.alive, 1, 3);


        if (EnumMatch.arenaType == EnumMatch.ARENA_TYPE_MATCH) {
            var matchScore = this.roomGameOverPush.kills * 1000 + this.roomGameOverPush.score * 100 + this.roomGameOverPush.alive;
            const fontClip_matchScore = this.fontClip_matchScore.getComponent(NumberIncrement);
            fontClip_matchScore.startIncrement(matchScore, 1, 1);
            this.img_matchScore.visible = true;
        }else{
            this.img_matchScore.visible = false;
        }

        // this.fontClip_kill.value = `${this.roomGameOverPush.kills}`;
        // this.fontClip_length.value = `${this.roomGameOverPush.length}`;
        // this.fontClip_challengeDuration.value = `${TimeUtil.format(this.roomGameOverPush.alive, ":", false)}`;

        if (this.arenaType == EnumMatch.MATCH_TYPE_PVP) {
            itemDtos = this.roomGameOverPush.items;
            tokens = this.roomGameOverPush.token;
            this.onSetReward(itemDtos, tokens);
        } else {
            FrameAiManager.sendAiEnd(this.roomGameOverPush.kills, this.roomGameOverPush.score);

            // var aiMsgEndBody: com.snake.socket.SC_AI_END = data[1];
            // itemDtos = aiMsgEndBody.items;
        }

        const tokenData = AssetManager.getTokenDataBySyId(10);
        console.log("tokenData===========>", tokenData);
    }

    private onSetReward(itemDtos: com.snake.socket.ItemObject[], tokens: string[]) {
        var items: ItemVo[] = [];
        var dic: Dictionary = new Dictionary();
        // var itemDtos:ItemDto[] = MatchModel.instance.reward;
        if (itemDtos && itemDtos.length > 0)
            itemDtos.forEach((itemDto) => {
                var itemVo = dic.get(itemDto.itemId);
                if (!itemVo) {
                    itemVo = new ItemVo(itemDto.itemId);
                    itemVo.newAddCnt = itemDto.num;
                    items.push(itemVo);
                    dic.set(itemDto.itemId, itemVo);
                } else {
                    itemVo.newAddCnt = itemVo.newAddCnt + itemDto.num;
                }
            });

        if (tokens && tokens.length > 0) {
            //token 击杀时间，被击杀国家，名字，id，数量
            tokens.forEach((tokenStr) => {
                var value = tokenStr.split(","); //击杀时间，被击杀国家，名字，id，数量

                var country = value[1];
                var nickName = value[2];
                var coinType = value[3];
                var coinNum = value[4];

                var m_iId = parseInt(coinType);
                var m_num = parseFloat(coinNum);

                var itemVo: ItemVo = dic.get(m_iId);
                if (!itemVo) {
                    itemVo = new ItemVo();
                    itemVo.type = EnumItemType.TYPE_TOKEN;
                    itemVo.id = m_iId;
                    itemVo.newAddCnt = m_num;
                    items.push(itemVo);
                    dic.set(m_iId, itemVo);
                } else {
                    itemVo.newAddCnt = itemVo.newAddCnt + m_num;
                }
            });
            // var itemVo = new ItemVo(EnumConsumeType.TYPE_REWARD_TOKEN);
            // items.push(itemVo);
        }

        var spaceX = this.list_reward.spaceX;
        var itemRenderW = (this.list_reward as any).itemTemplate.width;
        var len: number = items.length;
        var listW: number = len * itemRenderW + spaceX * (len - 1);
        this.list_reward.repeatX = len;
        this.list_reward.width = listW;
        this.list_reward.x = (this.box_outside.width - this.list_reward.width) >> 1;
        this.list_reward.array = items;
        this.list_reward.visible = true;
        if (!this.list_reward.array || this.list_reward.array.length <= 0) {
            if (this.arenaType == EnumMatch.MATCH_TYPE_PVE) {
                this.tf_ruleTip.text = GameLanguageMgr.getLanguage(610105);
                this.tf_ruleTip.visible = true;
                this.box_img.visible = false;
            } else {
                this.tf_ruleTip.visible = false;
                this.box_img.visible = true;
            }
            this.noDataBox1.visible = true;
        } else {
            this.noDataBox1.visible = false;
        }
        let selectIndex = -1;
        this.list_reward.selectedIndex = selectIndex;
    }

    private onAiEnd(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_AI_END = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_AI_END);
        var msgEndBody = msgBody as com.snake.socket.SC_AI_END;
        var items = msgEndBody.items;

        this.onSetReward(items, []);
    }

    private goFightAgain() {
        if (EnumMatch.arenaType == EnumMatch.ARENA_TYPE_PVP) {
            var pvpRoomIndex = MatchModel.roomDto.pvpRoomIndex;
            if (pvpRoomIndex < 0) {
                pvpRoomIndex = 0;
            }
            var pvpTokenIndex = MatchModel.roomDto.pvpTokenIndex;
            if (pvpTokenIndex < 0) {
                pvpTokenIndex = 0;
            }
            ModuleManager.intance.openModule(ModuleName.JoinRoomDialog, [pvpRoomIndex, pvpTokenIndex]);
        } else if (EnumMatch.arenaType == EnumMatch.ARENA_TYPE_JULEBU) {
            // 检查玩家是否有俱乐部
            const hasClub = GlobalDataManager.playerDto.club !== "" && GlobalDataManager.playerDto.club !== undefined;
            if (hasClub) {
                // 如果有俱乐部，跳转到俱乐部场景
                SceneManager.setCurrentScene(SceneType.M_SCENE_CLUB);
            } else {
                // 如果没有俱乐部，打开创建俱乐部对话框
                ModuleManager.intance.openModule(ModuleName.CreateClubDialog);
            }
        } else if (EnumMatch.arenaType == EnumMatch.ARENA_TYPE_PVE) {
            EnterRoomManager.goAiArenaScene();
        } else if (EnumMatch.arenaType == EnumMatch.ARENA_TYPE_MATCH) {
            SceneManager.setCurrentScene(SceneType.M_SCENE_MATCH_TOURNAMENT);
        }
    }

    onDisable(): void {
        this.removeEvent();
    }

    public removeEvent(): void {
        Signal.off("msg_" + com.snake.socket.MessageType.MSG_AI_END, this, this.onAiEnd);
    }
}
