import GameLanguageMgr from "../common/GameLanguageMgr";
import GlobalDataManager from "../global/GlobalDataManager";
/**
 * 数字工具类，提供各种数字格式化和转换方法
 */
export class NumberUtil {
    /**
     * 将数字保留指定小数位数
     * @param number 需要处理的数字
     * @param decimalPointCount 保留的小数位数
     * @returns 处理后的数字
     */
    public static toFixed(number: number, decimalPointCount: number): number {
        if (number.toString().indexOf(".") == -1) {
            return number;
        } else {
            let str: string = number.toFixed(decimalPointCount);
            return parseFloat(str);
        }
    }

    /**
     * 将数字转换为百分比格式
     * @param number 需要转换的数字
     * @param decimalPointCount 保留的小数位数
     * @param addStr 前缀字符串，默认为"+"
     * @returns 百分比格式的字符串，如"+50%"
     */
    public static toFixedWithPercent(number: number, decimalPointCount: number, addStr: string = "+"): string {
        let str: string;
        if (number.toString().indexOf(".") == -1) {
            str = addStr + number * 100 + "%";
        } else {
            decimalPointCount = decimalPointCount - 2;
            if (decimalPointCount < 0) {
                decimalPointCount = 0;
            }
            str = addStr + (number * 100).toFixed(decimalPointCount) + "%";
        }
        return str;
    }

    /**
     * 将金币数值格式化为带单位的字符串
     * @param num 金币数值
     * @returns 格式化后的字符串，超过999999显示为m单位
     */
    public static getGoldStr(num: any): string {
        let str: string;
        if (num > 999999) {
            str = parseInt(String(num / 100000)) + "m";
        } else {
            str = num;
        }
        return str;
    }

    /**
     * 将数字转换为千分位格式
     * @param num 需要格式化的数字字符串
     * @returns 添加千分位分隔符的字符串
     */
    public static numStringFormat(num: string): string {
        let str: string = num;
        if (GlobalDataManager.m_strLanguage == 2) {
            if (num.length > 4) {
                str = String(num).replace(/(\d)(?=(\d{3})+$)/g, "$1 ");
            }
        } else {
            str = String(num).replace(/(\d)(?=(\d{3})+$)/g, "$1,");
        }
        return str;
    }

    /**
     * 将数字简化为k单位的形式
     * @param num 需要简化的数字字符串
     * @returns 简化后的字符串，如1000转换为1k
     */
    public static numSimple(num: string): string {
        let str: string = num;
        let knum: number = parseInt(parseInt(str) / 1000 + "");
        if (knum > 0) {
            return knum + "k";
        }
        return NumberUtil.numStringFormat(str);
    }

    /**
     * 将数字格式化为带单位(K/M)的字符串
     * @param num 需要格式化的数字
     * @returns 格式化后的字符串
     */
    public static numStringFormat2(num: number): string {
        let str: string;
        if (num > 999999) {
            str = NumberUtil.getNumStr(num, 1000000, "M");
        } else if (num > 999) {
            str = NumberUtil.getNumStr(num, 1000, "K");
        } else {
            return num + "";
        }
        return str;
    }

    /**
     * 将数字转换为带单位的字符串
     * @param numI 需要转换的数字
     * @param numM 单位基数
     * @param lauguage 单位字符串
     * @returns 格式化后的字符串
     */
    public static getNumStr(numI: number, numM: number, lauguage: string): string {
        let str: string = parseInt(Math.floor(numI / numM) + "") + lauguage;
        return str;
    }

    /**
     * 将时间数值转换为格式化的时间字符串
     * @param times 时间数值（单位：秒）
     * @returns 格式化后的时间字符串，根据时间长短显示为分钟、小时或天数
     */
    public static getTimeStr(times: number): string {
        let str: string;
        if (times < 3600) {
            str = GameLanguageMgr.getLanguage(9024, Math.ceil(times / 60));
        } else if (times < 3600 * 24) {
            str = GameLanguageMgr.getLanguage(9025, Math.ceil(times / 3600));
        } else {
            str = GameLanguageMgr.getLanguage(9025, Math.ceil(times / (3600 * 24)));
        }
        return str;
    }

    /**
     * 判断一个数字是否为整数
     * @param obj 需要判断的数字
     * @returns 如果是整数返回true，否则返回false
     */
    public static isInteger(obj: number): boolean {
        return obj % 1 === 0;
    }

    /**
     * 判断一个值是否为数字类型
     * @param value 需要判断的值
     * @returns 如果是数字类型返回true，否则返回false
     */
    public static isNumber(value: unknown): value is number {
        return typeof value === "number";
    }

    /**
     * 格式化数字，对于非整数保留指定位数的小数
     * @param num 需要格式化的数字
     * @param digits 保留的小数位数，默认为8位
     * @returns 格式化后的数字
     */
    static formatNumber(num: number, digits = 8): number {
        if (Number.isInteger(num)) {
            // 如果是整数，直接转换为字符串
            return num;
        } else {
            // 如果不是整数，保留两位小数
            return parseFloat(num.toFixed(digits));
        }
    }

    /**
     * 格式化数字为字符串，对于非整数保留指定位数的小数
     * @param num 需要格式化的数字
     * @param digits 保留的小数位数，默认为2位
     * @returns 格式化后的数字字符串
     */
    static formatNumberStr(num: number, digits = 2): any {
        if (Number.isInteger(num)) {
            // 如果是整数，直接转换为字符串
            return num;
        } else {
            // 如果不是整数，保留两位小数
            return parseFloat(num.toFixed(digits)).toString();
        }
    }

    /**
     * @param num
     * @param digits
     * @param needK
     * @param isFloor 是否向下取的小数
     * @returns
     */
    public static filterNumFormat(num: any, digits = 2, needK: boolean = false, isFloor = false): string {
        if (!num) {
            return num;
        }
        if (num < 1e3 && num > 0) {
            if (isFloor) {
                var tempNum = Math.floor(Number(parseFloat(num * 10 ** digits + "").toPrecision(16))) / 10 ** digits;
                return parseFloat(tempNum.toFixed(digits)).toString();
            } else {
                return parseFloat(num.toFixed(digits)).toString();
            }
        }

        if (num === "0.00") return num;
        var si = [
            { value: 1, symbol: "" },
            { value: 1e6, symbol: "M" },
            { value: 1e9, symbol: "G" },
            { value: 1e12, symbol: "T" },
            { value: 1e15, symbol: "P" }
        ];
        if (needK) {
            si = [
                { value: 1, symbol: "" },
                { value: 1e3, symbol: "k" },
                { value: 1e6, symbol: "M" },
                { value: 1e9, symbol: "G" },
                { value: 1e12, symbol: "T" },
                { value: 1e15, symbol: "P" }
            ];
        }
        var rx = /\.0+$|(\.[0-9]*[1-9])0+$/;
        var i;
        for (i = si.length - 1; i > 0; i--) {
            if (num >= si[i].value) {
                break;
            }
        }
        let temp = (num / si[i].value).toString();
        if (temp.indexOf(".") > -1) {
            if (digits > 0) temp = temp.substr(0, temp.indexOf(".") + digits + 1);
            else temp = temp.substr(0, temp.indexOf(".") + digits);
        }
        return temp.replace(rx, "$1") + si[i].symbol;
    }

    /**
     * 将区块链中的Wei单位数值转换为普通数值
     * @param value 原始Wei单位的数值字符串
     * @param decimals 代币的小数位数
     * @param point 需要保留的小数位数，默认为0
     * @returns 转换后的数值字符串，如果输入无效则返回0
     */
    public static fromWei(value: any, decimals: number, point = 0) {
        if (!value) {
            return 0;
        }
        let len = value.length - decimals + point;
        if (len <= 0) {
            return 0;
        }
        let temp = value.toString().slice(0, len);
        if (point) {
            let tt = temp.length - point;
            if (tt <= 0) {
                let ttt = "0.";
                for (let index = 0; index < Math.abs(tt); index++) {
                    ttt += "0";
                }
                temp = ttt + temp;
            } else {
                temp = temp.slice(0, temp.length - point) + "." + temp.slice(temp.length - point);
            }
        }
        return temp;
    }

    /**
     * 获取数字的后9位数字，用于处理大数值的显示
     * @param numStr 需要处理的数字字符串
     * @returns 返回数字的后9位，如果输入无效则返回原字符串
     */
    public static getNumberSuffix(numStr: string): string {
        const num = parseInt(numStr, 10);
        if (isNaN(num)) {
            return numStr;
        }
        return (num % 1000000000).toString();
    }

    public static formatCurrencyPrice(price: number) {
        // 处理科学计数法，转为普通小数字符串
        let priceStr = String(price);
        if (priceStr.includes('e') || priceStr.includes('E')) {
            // 转为普通小数
            priceStr = price.toFixed(20).replace(/0+$/, '');
        }
        if (!priceStr.includes('.')) {
            return priceStr; // 整数直接返回
        }
        const [integerPart, decimalPartRaw] = priceStr.split('.');
        // 如果小数部分全是0
        if (!decimalPartRaw || /^0+$/.test(decimalPartRaw)) {
            return integerPart;
        }
        // 匹配前导0
        const leadingZerosMatch = decimalPartRaw.match(/^0+/);
        let result = integerPart + '.';
        if (leadingZerosMatch) {
            const zeroCount = leadingZerosMatch[0].length;
            // 如果前导0少于2位，直接显示完整的小数
            if (zeroCount < 2) {
                result += decimalPartRaw.slice(0, 4);
            } else {
                result += `0{${zeroCount}}`;
                // 截取后面最多4位有效数字
                const validDecimal = decimalPartRaw.slice(zeroCount, zeroCount + 4);
                result += validDecimal;
            }
        } else {
            // 没有前导0，直接取最多4位
            result += decimalPartRaw.slice(0, 4);    
        }
        return result;
    }

    /**
     * 带连续0判断的货币格式化：
     * - 如果小数点后连续0超过4个且后面有非0数字，只返回整数部分
     * - 其它情况用formatCurrencyPrice处理
     */
    public static formatCurrencyPriceWithZeroCheck(price: number) {
        // 处理科学计数法
        let priceStr = String(price);
        if (priceStr.includes('e') || priceStr.includes('E')) {
            priceStr = price.toFixed(20).replace(/0+$/, '');
        }
        if (!priceStr.includes('.')) {
            return priceStr;
        }
        const [integerPart, decimalPartRaw] = priceStr.split('.');
        if (!decimalPartRaw || /^0+$/.test(decimalPartRaw)) {
            return integerPart;
        }
        // 整数部分不为0时，直接返回整数+小数点后最多4位
        if (parseInt(integerPart) > 0) {
            return `${integerPart}.${decimalPartRaw.slice(0, 4)}`;
        }
        // 匹配前导0
        const leadingZerosMatch = decimalPartRaw.match(/^0+/);
        if (leadingZerosMatch) {
            const zeroCount = leadingZerosMatch[0].length;
            const hasNonZeroAfter = decimalPartRaw.slice(zeroCount).match(/[^0]/);
            if (zeroCount > 4 && hasNonZeroAfter) {
                return integerPart;
            }
        }
        // 其它情况用原有方法（此时integerPart为0）
        return this.formatCurrencyPrice(price);
    }
    
    /**
     * 保留两位小数，结尾是0则去掉，若全为0则不显示小数部分
     */
    public static formatTrimZeroDecimal2(num: number, digits: number = 2) {
        let str = num.toFixed(digits);
        // 去掉结尾的0
        str = str.replace(/0+$/, '');
        // 如果最后是小数点，也去掉
        str = str.replace(/\.$/, '');
        return str;
    }

    public static formatSmartCurrency(price: number) {
        // 科学计数法转普通字符串（不四舍五入）
        let priceStr = String(price);
        if (priceStr.includes('e') || priceStr.includes('E')) {
            // 利用BigInt和字符串处理，避免精度丢失和四舍五入
            const parts = priceStr.toLowerCase().split('e');
            let base = parts[0];
            let exp = Number(parts[1]);
            if (base.includes('.')) {
                const [intPart, decPart] = base.split('.');
                let digits = intPart + decPart;
                let dotPos = intPart.length;
                let newDotPos = dotPos + exp;
                if (exp < 0) {
                    digits = '0'.repeat(Math.abs(exp) - 1) + digits;
                    newDotPos = 1;
                }
                if (newDotPos < digits.length) {
                    priceStr = digits.slice(0, newDotPos) + '.' + digits.slice(newDotPos);
                } else {
                    priceStr = digits + '0'.repeat(newDotPos - digits.length);
                }
            } else {
                let digits = base;
                let newDotPos = digits.length + exp;
                if (exp < 0) {
                    digits = '0'.repeat(Math.abs(exp) - 1) + digits;
                    newDotPos = 1;
                }
                if (newDotPos < digits.length) {
                    priceStr = digits.slice(0, newDotPos) + '.' + digits.slice(newDotPos);
                } else {
                    priceStr = digits + '0'.repeat(newDotPos - digits.length);
                }
            }
            priceStr = priceStr.replace(/\.0+$/, '');
        }
        if (!priceStr.includes('.')) {
            return priceStr;
        }
        const [integerPart, decimalPartRaw] = priceStr.split('.');
        if (!decimalPartRaw || /^0+$/.test(decimalPartRaw)) {
            return integerPart;
        }
        if (parseInt(integerPart) > 0) {
            return `${integerPart}.${decimalPartRaw.slice(0, 4)}`;
        }
        const leadingZerosMatch = decimalPartRaw.match(/^0+/);
        if (leadingZerosMatch) {
            const zeroCount = leadingZerosMatch[0].length;
            const hasNonZeroAfter = decimalPartRaw.slice(zeroCount).match(/[^0]/);
            if (zeroCount > 4 && hasNonZeroAfter) {
                return integerPart;
            }
            let result = integerPart + '.';
            result += `0{${zeroCount}}`;
            const validDecimal = decimalPartRaw.slice(zeroCount, zeroCount + 4);
            result += validDecimal;
            return result;
        }
        return `${integerPart}.${decimalPartRaw.slice(0, 4)}`;
    }
}
