const { regClass } = Laya;
import { SceneType } from "../../common/baseScene/SceneType";
import GameLanguageMgr from "../../common/GameLanguageMgr";
import { LayerManager } from "../../common/LayerManager";
import SceneManager from "../../common/SceneManager";
import { EnumItemType } from "../../data/enumData/EnumItemType";
import { ItemVo } from "../../data/vo/pack/ItemVo";
import GlobalDataManager from "../../global/GlobalDataManager";
import { Dictionary } from "../../utils/Dictionary";
import { SettleDialogBase } from "./SettleDialog.generated";

@regClass('JjhIIfhPRp251zGtjLBPmA==')
export class SettleDialog extends SettleDialogBase {
    public m_iLayerType: number;
    public m_iPositionType: number;
    onAwake(): void {
        this.m_iLayerType = LayerManager.M_POP;
        this.m_iPositionType = LayerManager.UP;
    }

    public setOpenData(datas: any) {
        console.log("datas", datas);
        let playerData = datas[1];//对手信息
        let settleData = datas[0];//结算信息
        this.setEnemyData(playerData);
        this.setSettleData(settleData);
    }

    onEnable(): void {
        // this.tf_scoreTx.text = GameLanguageMgr.getLanguage(3005);

        this.btn_continue.on(Laya.Event.CLICK, this, this.onClickContinue);
        this.btn_close.on(Laya.Event.CLICK, this, this.onClickBackHome);
        this.btn_exit.on(Laya.Event.CLICK, this, this.onClickBackHome);
    }

    private setEnemyData(playerData: any) {
        let enemyData = playerData.players.find((item) => item.roleId != GlobalDataManager.playerDto.pid);
        if (enemyData) {
            this.tf_name.text = enemyData.userName;
            this.playerIcon.dataSource = enemyData;
        }
    }

    private setSettleData(settleData: any) {
        let item = settleData.items;
        let tokens = settleData.token;
        var dic: Dictionary = new Dictionary();
        var items: ItemVo[] = [];
        var dic: Dictionary = new Dictionary();
        // var itemDtos:ItemDto[] = MatchModel.instance.reward;
        if (item && item.length > 0)
            item.forEach((itemDto) => {
                var itemVo = dic.get(itemDto.itemId);
                if (!itemVo) {
                    itemVo = new ItemVo(itemDto.itemId);
                    itemVo.newAddCnt = itemDto.num;
                    items.push(itemVo);
                    dic.set(itemDto.itemId, itemVo);
                } else {
                    itemVo.newAddCnt = itemVo.newAddCnt + itemDto.num;
                }
            });
        if (tokens && tokens.length > 0) {
            //token 击杀时间，被击杀国家，名字，id，数量
                var value = tokens.split(","); //击杀时间，被击杀国家，名字，id，数量
                var coinType = value[0];
                var coinNum = value[1];

                var m_iId = parseInt(coinType);
                var m_num = parseFloat(coinNum);

                var itemVo: ItemVo = dic.get(m_iId);
                if (!itemVo) {
                    itemVo = new ItemVo();
                    itemVo.type = EnumItemType.TYPE_TOKEN;
                    itemVo.id = m_iId;
                    itemVo.newAddCnt = m_num;
                    items.push(itemVo);
                    dic.set(m_iId, itemVo);
                } else {
                    itemVo.newAddCnt = itemVo.newAddCnt + m_num;
                }
            // var itemVo = new ItemVo(EnumConsumeType.TYPE_REWARD_TOKEN);
            // items.push(itemVo);
        }
        
        // 根据截图中的写法计算列表居中
        var spaceX = this.propList.spaceX;
        var itemRenderW = (this.propList as any).itemTemplate.width;
        var len: number = items.length;
        var listW: number = len * itemRenderW + spaceX * (len - 1);
        this.propList.repeatX = len;
        this.propList.width = listW;
        this.propList.x = ((this.box_outside.width - this.propList.width) >> 1) - 50;
        this.propList.array = items;
        this.propList.visible = true;
        if(items.length > 2){
            this.img_qbg.width = 500
        }else{
            this.img_qbg.width = 362
        }
        this.tf_tittle.text = settleData.res == true ? "Victory" : "Defeat";
        this.tf_tittle2.text = this.tf_tittle.text;
        this.tf_result.text = settleData.res == true ? "You have defeated" : "You lost to";
        this.nameBox.width = this.tf_result.width + 14 + 110 + this.tf_name.width;
        // this.img_result.skin = settleData.res == true ? "res/tetris/settle/img_role1.png" : "res/tetris/settle/img_role2.png";
        this.tf_score.text = settleData.score;
        this.tf_rank.text = GameLanguageMgr.getLanguage(3004, settleData.mmr);
        if(settleData.res){
            this.successBox.visible = true;
            this.failBox.visible = false;
        }else{
            this.successBox.visible = false;
            this.failBox.visible = true;
        }
    }



    onDisable(): void {
        SceneManager.setCurrentScene(SceneType.M_SCENE_MAIN);
        this.btn_continue.off(Laya.Event.CLICK, this, this.onClickContinue);
        this.btn_close.off(Laya.Event.CLICK, this, this.onClickBackHome);
        this.btn_exit.off(Laya.Event.CLICK, this, this.onClickBackHome);
    }

    private onClickContinue() {
        GlobalDataManager.needToOpenJoinRoom = true;
        this.close()
    }


    private onClickBackHome() {
        this.close()
    }
}
