const { regClass } = Laya;
import { MatchEndRewardTokensDialogBase } from "./MatchEndRewardTokensDialog.generated";
import { MatchEndRewardTokensListItem } from "./MatchEndRewardTokensListItem";
import MatchModel from "./MatchModel";

@regClass('JH3DtUPTS/2FR6dTzhLHMw==')
export class MatchEndRewardTokensDialog extends MatchEndRewardTokensDialogBase {
    public constructor() {
        super();
    }

    onEnable(): void {
        this.list.visible = false;

        var msgEndbody = MatchModel.msgEndbody;

        var tokens: string[] = msgEndbody.token;
        // 设置List的渲染处理器
        this.list.renderHandler = new Laya.Handler(this, (cell: MatchEndRewardTokensListItem, index: number) => {
            // 将index动态传递给ListItem
            cell.setDataIndex(index); // 自定义方法
        });

        this.list.array = tokens;
        this.list.visible = true;
        if (!tokens || tokens.length <= 0) {
            this.noDataBox.visible = true;
        } else {
            this.noDataBox.visible = false;
        }
    }

    onDisable(): void {}
}
