/**
 * 跑马灯工具类
 * 提供跑马灯相关的工具方法
 */

import { GameEvent } from "../../global/event/GameEvent";
import Signal from "../../global/event/Signal";
import MarqueeManager from "./MarqueeManager";

export default class MarqueeUtils {
    /**
     * 模拟服务器推送新公告
     * @param notice 公告内容
     */
    public static pushNotice(notice: string): void {
        // 触发新公告事件
        Signal.event(GameEvent.EVENT_NEW_NOTICE, notice);
    }
    
    /**
     * 启动自动推送测试公告
     * 用于开发测试，每隔指定时间推送一条随机公告
     * @param interval 推送间隔（毫秒）
     */
    public static startAutoPush(interval: number = 60000): void {
        // 测试公告内容 - 控制长度，避免过长文本
        const testNotices = [
            "测试测试测试测试测试测试测试测试测试测试测试测试测试测试测试测试测试测试测试测试测试测试",
            "欢迎来到nake游戏，祝您游戏愉快！",
            "新版本V1.2.5已发布，增加了新的游戏玩法和优化了游戏体验。",
            "游戏将于明日凌晨2:00-4:00进行维护，请提前做好准备。",
            "服务器即将进行维护，预计停机时间2小时。"
        ];
        
        // 定时推送 - 增加间隔时间到60秒
        Laya.timer.loop(interval, null, () => {
            // 随机选择一条公告
            const randomIndex = Math.floor(Math.random() * testNotices.length);
            const notice = testNotices[randomIndex];
            
            // 推送公告
            this.pushNotice(notice);
        });
    }
    
    /**
     * 停止自动推送
     */
    public static stopAutoPush(): void {
        Laya.timer.clearAll(null);
    }
    
    /**
     * 清空当前所有公告
     */
    public static clearAllNotices(): void {
        MarqueeManager.clearNotices();
    }
} 