    public m_iLayerType: number;
    public m_iPositionType: number;

    gridScript: GridView; // 网格视图脚本
    gameModel: GameModel; // 游戏模型
    isInPlayAni: boolean; // 是否在动画中
    isCanMove: boolean; // 是否可以移动
    stepCount: number;
    // timeLeft: number;
    bossHp: number;
    score: number = 0;
    comboCount: number = 0;
    levelConfig: LevelConfig;
    currentLevelId: number = 1;

