const { regClass } = Laya;

@regClass('HmgDdOmWSJaQST7GGmoBkQ==')
export class DayListItem extends DayListItemBase {
    isAddEvent: boolean;
    public set dataSource(value: any) {
        super.dataSource = value;
        if(value){
            // globalDataManager.tokenData里面筛选出symbolId与value.ticketType相等的项目
            // let tokenData = AssetManager.getTokenDataBySyId(value)
            // let tokenData = GlobalDataManager.tokenData.find(item => item.symbolId == value);
            this.tf_data.text = value.formatted;
        }
    }

    onDisable(): void {
    }

    private onChange(isSelect:boolean){
        if(isSelect){
            this.selectImg.visible = true;
            this.tf_data.color = "#ffffff";
        }else{
            this.tf_data.color = "#5a9ee0";
            this.selectImg.visible = false;
        }
    }
}
