const { regClass } = Laya;

@regClass('+Eiy8bdxSiik3SKAQH57mw==')
export class NetListItem extends NetListItemBase {
    isAddEvent: boolean;
    public set dataSource(value: any) {
        super.dataSource = value;
        if(value){
            this.tf_data.text = value.chainName;
            this.img_icon.skin = GameResourceManager.getChainIcon(value.chainId);

            // globalDataManager.tokenData里面筛选出symbolId与value.ticketType相等的项目
            // let tokenData = AssetManager.getTokenDataBySyId(value)
            // // let tokenData = GlobalDataManager.tokenData.find(item => item.symbolId == value);
            // this.tf_data.text = tokenData.symbol;
            // this.img_coin.skin = GameResourceManager.getCurrencyIcon(tokenData.symbolId)
        }
    }

    onDisable(): void {
    }

    private onChange(isSelect:boolean){
        if(isSelect){
            this.selectImg.visible = true;
            this.tf_data.color = "#ffffff";
        }else{
            this.tf_data.color = "#357cc0";
            this.selectImg.visible = false;
        }
    }
}
