import CellView from "../view/CellView";
import { CELL_NAME_PREFIX } from "./ConstValue";

/**
 *
 */
class DataManger {
  private static _instance: DataManger;
  public static getInstance(): DataManger {
    if (!DataManger._instance) DataManger._instance = new DataManger();
    return DataManger._instance;
  }

  // 资源缓存
  public elementPrefabs: Record<string, Laya.Prefab> = {};
  public obstaclePrefabs: Record<string, Laya.Prefab> = {};
  public cellViewPrefab: Laya.Prefab;

  public grid: Laya.Sprite;

  findCellNodeByID(id: number): CellView {
    for (let i = 0; i < this.grid.numChildren; i++) {
      const child = this.grid.getChildAt(i) as CellView;
      if (child.name === CELL_NAME_PREFIX + id) return child;
    }
    return null;
  }
}

export default DataManger.getInstance();
