import { TimeUtil } from "../../utils/TimeUtil";
import { MillListItemBase } from "./MillListItem.generated";
const { regClass } = Laya;

@regClass('3h2PsGTIQV6ilXcpYeJ0cQ==')
export class MillListItem extends MillListItemBase {
    public mailItem: any;

    public constructor() {
        super();
    }

    onEnable(): void {
    }
    //橙色  fdd378

    public set dataSource(value: any) {
        super.dataSource = value;
        this.mailItem = value as any;
        if (!this.mailItem) {
            return;
        }
        this.tf_title.text = this.mailItem.title;
        this.tf_from.text = this.mailItem.sendName;
        this.img_red.visible = !this.mailItem.read;
        this.tf_time.text = TimeUtil.formatTimeAgoFromTimestamp(this.mailItem.sendTime);
    }
}
