import Constants from "../../global/config/Constants";
import { Vec2 } from "../../utils/Vec2";
import QuadTree from "./QuadTree";

export class Collision {
    private static instance: Collision | null = null;

    quadTree: QuadTree<any>;

    /**
     * 获取单例实例
     * @param bounds 碰撞检测区域范围（Laya.Rectangle）
     */
    public static getInstance(bounds: Laya.Rectangle = null): Collision {
        if (!Collision.instance) {
            if (!bounds) {
                bounds = new Laya.Rectangle(0, 0, Constants.mapSize.width, Constants.mapSize.height);
            }
            Collision.instance = new Collision(bounds);
        }
        return Collision.instance;
    }

    constructor(bounds: Laya.Rectangle) {
        this.quadTree = new QuadTree(bounds);
    }

    /**
     * 添加一组对象到碰撞四叉树中
     * @param skins 数组，每个对象须实现 getBoundingBox() 方法
     */
    public addSnake(skins: any[]): void {
        skins.forEach((v) => {
            this.quadTree.insert(v);
        });
    }
    /**
     * 添加对象到碰撞四叉树中
     * @param skin，每个对象须实现 getBoundingBox() 方法
     */
    public addBodySkin(skin: any): void {
        this.quadTree.insert(skin);
    }

    /**
     * 从碰撞四叉树中移除一组对象
     * @param skins 数组，每个对象须实现 getBoundingBox() 方法
     */
    public removeSnake(skins: any[]): void {
        skins.forEach((v) => {
            this.quadTree.remove(v);
        });
    }
    /**
     * 从碰撞四叉树中移除对象
     * @param skin，每个对象须实现 getBoundingBox() 方法
     */
    public removeBodySkin(skin: any): void {
        this.quadTree.remove(skin);
    }

    /**
     * 刷新四叉树，将所有对象动态更新到正确的象限中
     */
    public refresh(): void {
        this.quadTree.refresh();
    }
    /**
     * drawDebug
     */
    public drawDebug(graphics: Laya.Graphics): void {
        this.quadTree.drawDebug(graphics);
    }

    /**
     * 检索可能与给定对象碰撞的对象集合
     * @param node 对象须实现 getBoundingBox() 方法
     */
    public retrieve(node: { getBoundingBox: () => Laya.Rectangle }): any[] {
        return this.quadTree.retrieve(node);
    }

    public raycast(start: Vec2, end: Vec2, filter: (obj: any) => boolean): boolean {
        return this.quadTree.raycast(start, end, filter);
    }

    //=========== 添加绘制方法 ===============
    // Collision.ts 添加新方法
    public getAllCollidables(): any[] {
        return this._getAllFromQuadTree(this.quadTree);
    }

    private _getAllFromQuadTree(node: QuadTree<any>): any[] {
        let result = [...node.objects];
        node.nodes.forEach((child) => {
            result = result.concat(this._getAllFromQuadTree(child));
        });
        return result;
    }
}
