const { regClass } = Laya;
// 修改导入方式：直接导入类而不是实例
import { TetrisType, BLOCK_COLORS } from "./GameManager";
import { Cell } from "./Cell";
import { NetworkSyncManager } from "./NetworkSyncManager";

/**
 * PVP俄罗斯方块游戏管理器
 * 使用组合模式而不是继承，包装GameManager实例
 */
@regClass('mQH2BXyDQ8eNZIvW0Ea4Iw==')
export class PvpGameManager {
    private static _instance: PvpGameManager = null;
    
    // 组合使用GameManager实例而不是继承
    private gameManager: any; // GameManager实例
    
    // 网络同步管理器
    private networkSync: NetworkSyncManager;
    
    // 对手游戏状态
    private opponentGameMatrix: Cell[][] = [];
    private opponentScore: number = 0;
    private opponentIsGameOver: boolean = false;
    
    // PVP特有回调
    private onOpponentStateUpdated: Function;
    private onAttackReceived: Function;
    private onGameResult: Function;
    
    /**
     * 构造函数
     */
    private constructor() {
        // 获取GameManager单例实例
        this.gameManager = require('./GameManager').default;
        this.initOpponentMatrix();
    }
    
    /**
     * 获取单例实例
     */
    public static getInstance(): PvpGameManager {
        if (!PvpGameManager._instance) {
            PvpGameManager._instance = new PvpGameManager();
        }
        return PvpGameManager._instance;
    }
    
    /**
     * 初始化对手游戏矩阵
     */
    private initOpponentMatrix(): void {
        this.opponentGameMatrix = [];
        for (let row = 0; row < 20; row++) {
            this.opponentGameMatrix[row] = [];
            for (let col = 0; col < 10; col++) {
                this.opponentGameMatrix[row][col] = new Cell();
            }
        }
    }
    
    /**
     * 初始化PVP游戏管理器
     */
    public initPvp(callbacks: {
        onDrawCurrentTetris: Function,
        onDrawFixedBlocks: Function,
        onDrawNextTetris: Function,
        onDrawHoldTetris: Function,
        onScoreUpdated: Function,
        onGameOver: Function,
        onOpponentStateUpdated?: Function,
        onAttackReceived?: Function,
        onGameResult?: Function
    }): void {
        // 初始化GameManager
        this.gameManager.setCallbacks({
            onDrawCurrentTetris: callbacks.onDrawCurrentTetris,
            onDrawFixedBlocks: callbacks.onDrawFixedBlocks,
            onDrawNextTetris: callbacks.onDrawNextTetris,
            onDrawHoldTetris: callbacks.onDrawHoldTetris,
            onScoreUpdated: callbacks.onScoreUpdated,
            onGameOver: callbacks.onGameOver
        });
        
        // 设置PVP特有回调
        this.onOpponentStateUpdated = callbacks.onOpponentStateUpdated;
        this.onAttackReceived = callbacks.onAttackReceived;
        this.onGameResult = callbacks.onGameResult;
        
        // 初始化网络同步管理器
        this.networkSync = NetworkSyncManager.getInstance();
        this.networkSync.init({
            onGameSync: this.handleGameSync.bind(this),
            onOpponentAction: this.handleOpponentAction.bind(this),
            onAttackLines: this.handleAttackLines.bind(this)
        });
    }
    
    // ========== 委托GameManager的方法 ==========
    
    /**
     * 开始游戏
     */
    public startGame(): void {
        this.gameManager.startGame();
        // this.networkSync.startSync();
    }
    
    /**
     * 向左移动
     */
    public moveLeft(): boolean {
        const result = this.gameManager.moveLeft();
        if (result) {
            this.syncActionToNetwork('moveLeft', {});
        }
        return result;
    }
    
    /**
     * 向右移动
     */
    public moveRight(): boolean {
        const result = this.gameManager.moveRight();
        if (result) {
            this.syncActionToNetwork('moveRight', {});
        }
        return result;
    }
    
    /**
     * 向下移动
     */
    public moveDown(): boolean {
        const result = this.gameManager.moveDown();
        if (result) {
            this.syncActionToNetwork('moveDown', {});
        }
        return result;
    }
    
    /**
     * 旋转方块
     */
    public rotateTetris(): boolean {
        const result = this.gameManager.rotateTetris();
        if (result) {
            this.syncActionToNetwork('rotate', {});
        }
        return result;
    }
    
    /**
     * 快速下落
     */
    public quickDrop(): boolean {
        const result = this.gameManager.quickDrop();
        if (result) {
            this.syncActionToNetwork('quickDrop', {});
        }
        return result;
    }
    
    /**
     * Hold方块
     */
    public holdTetris(): boolean {
        const result = this.gameManager.holdTetris();
        if (result) {
            this.syncActionToNetwork('hold', {});
        }
        return result;
    }
    
    /**
     * 获取游戏状态
     */
    public isRunning(): boolean {
        return this.gameManager.isRunning();
    }
    
    /**
     * 获取分数
     */
    public getScore(): number {
        return this.gameManager.getScore();
    }
    
    /**
     * 获取游戏矩阵
     */
    public getGameMatrix(): Cell[][] {
        return this.gameManager.getGameMatrix();
    }
    
    // ========== PVP特有方法 ==========
    
    /**
     * 发送攻击行给对手
     */
    public sendAttackLines(lines: number): void {
        this.networkSync.sendAttackLines(lines);
    }
    
    /**
     * 接收对手发送的攻击行
     */
    public receiveAttackLines(lines: number): void {
        // 在游戏区域底部添加垃圾行
        for (let i = 0; i < lines; i++) {
            this.gameManager.moveBlocksUp();
        }
        
        // 触发攻击接收回调
        if (this.onAttackReceived) {
            this.onAttackReceived(lines);
        }
    }
    
    /**
     * 获取对手游戏状态
     */
    public getOpponentGameState(): {
        gameMatrix: Cell[][],
        score: number,
        isGameOver: boolean
    } {
        return {
            gameMatrix: this.opponentGameMatrix,
            score: this.opponentScore,
            isGameOver: this.opponentIsGameOver
        };
    }
    
    /**
     * 根据消除行数计算伤害值
     * @param lines 消除的行数
     * @returns 伤害值（1行消除=200伤害，2行消除=600伤害，3行消除=1200伤害，4行及以上消除=3000伤害）
     */
    public calculateDamage(lines: number): number {
        // 大于4行的按4行计算
        const effectiveLines = Math.min(lines, 4);
        
        switch (effectiveLines) {
            case 1:
                return 200;
            case 2:
                return 600;
            case 3:
                return 1200;
            case 4:
                return 3000;
            default:
                return ;
        }
    }
    
    /**
     * 同步操作到网络
     */
    private syncActionToNetwork(actionType: string, data: any): void {
        this.networkSync.sendGameAction(actionType, data);
    }
    
    /**
     * 处理游戏同步消息
     */
    private handleGameSync(data: any): void {
        // 更新对手游戏状态
        if (data.gameMatrix) {
            this.updateOpponentMatrix(data.gameMatrix);
        }
        if (data.score !== undefined) {
            this.opponentScore = data.score;
        }
        if (data.isGameOver !== undefined) {
            this.opponentIsGameOver = data.isGameOver;
            if (data.isGameOver && this.onGameResult) {
                this.onGameResult('win'); // 对手游戏结束，我方获胜
            }
        }
        
        // 触发对手状态更新回调
        if (this.onOpponentStateUpdated) {
            this.onOpponentStateUpdated(this.getOpponentGameState());
        }
    }
    
    /**
     * 处理对手操作
     */
    private handleOpponentAction(data: any): void {
        // 根据对手操作类型进行相应处理
        console.log('对手操作:', data.actionType, data.data);
        
        // 可以在这里添加对手操作的视觉效果等
    }
    
    /**
     * 处理攻击行消息
     */
    private handleAttackLines(data: any): void {
        const lines = data.lines || 0;
        if (lines > 0) {
            this.receiveAttackLines(lines);
        }
    }
    
    /**
     * 更新对手游戏矩阵
     */
    private updateOpponentMatrix(matrixData: any[][]): void {
        for (let row = 0; row < matrixData.length && row < this.opponentGameMatrix.length; row++) {
            for (let col = 0; col < matrixData[row].length && col < this.opponentGameMatrix[row].length; col++) {
                if (matrixData[row][col]) {
                    this.opponentGameMatrix[row][col].copyFrom(matrixData[row][col]);
                } else {
                    this.opponentGameMatrix[row][col].setEmpty();
                }
            }
        }
    }
    
    /**
     * 销毁PVP游戏管理器
     */
    public destroy(): void {
        // 销毁网络同步管理器
        if (this.networkSync) {
            this.networkSync.destroy();
        }
        
        // 如果有GameManager实例，也需要销毁
        if (this.gameManager && this.gameManager.dispose) {
            this.gameManager.dispose();
        }
        
        // 清理实例
        PvpGameManager._instance = null;
    }
}