    // 新增属性
    private _smoothDelay: number = 0; // 平滑后的延迟

    private _alpha: number = 0.2; // 平滑系数 (0.2表示新值占20%权重)

    // 在收到服务器时间同步响应时更新延迟（示例位置）
    public updateNetworkLatency(clientSendTime: number): void {
        // 计算最新往返延迟（RTT）
        const now = Date.now();
        const latestRTT = now - clientSendTime;
        Signal.event(GameEvent.EVENT_Game_Room_Delay, latestRTT);

        // 计算单程延迟估计（假设对称网络）
        const latestDelay = latestRTT / 2;

        // 首次初始化
        if (this._smoothDelay === 0) {
            this._smoothDelay = latestDelay;
        } else {
            // 应用指数平滑公式：smooth = α*latest + (1-α)*previous
            this._smoothDelay = this._alpha * latestDelay + (1 - this._alpha) * this._smoothDelay;
        }

        // 更新全局延迟估计
        RoomWebSocket.delaT = this._smoothDelay;
        RoomWebSocket._lastRTT = latestRTT;

        // 调试输出
        if (GameSetting.Debug) {
            console.log(`[Latency] RTT: ${latestRTT}ms, 平滑延迟: ${this._smoothDelay.toFixed(1)}ms`);
        }

        // 在 updateNetworkLatency 中增加
        if (latestRTT > 1000) {
            // 超过1秒的延迟
        }
    }
