    public clientSendTime: number;

    /**
     * 请求次数
     */
    private requestTime: number = 0;

    /**
     * 开始发起对时
     *  */
    private onStartRequestTime(): void {
        this.requestTime = 0;
        this.onRequestTime();
    }
    /**
     * 发起对时
     *  */
    private onRequestTime(): void {
        this.clientSendTime = Date.now(); // 发送时间
        var cmdId = com.snake.socket.MessageType.MSG_REQUEST_SERVER_TIME;
        var o = null;
        RoomWebSocket.sendData(cmdId, o);
    }
    /**
     * 请求比赛数据
     */
    private onGetEnterRoomData(): void {
        // if(this.isFirst){//  连接类型 : 普通连接
        // socket链接上后，触发open事件时，发送登录或重连数据
        var roomNo = MatchModel.roomDto.roomNo;
        var symbol = MatchModel.roomDto.symbol;
        var roleId = GlobalDataManager.playerDto.pid;
        var isWatch = MatchModel.roomDto.isWatch;

        var cmdId = com.snake.socket.MessageType.MSG_ENTER_ROOM;
        var o = com.snake.socket.CS_ENTER_ROOM.fromObject({
            tag: roomNo,
            symbol: symbol,
            roleId: roleId,
            watch: isWatch
        });
        RoomWebSocket.sendData(cmdId, o);
    }

    /**
     * 对时返回
     * @param msgBase
     * @param msgcode
     */
    private onRecvServerTime(msgBase: com.snake.socket.CMsgBase, msgcode: number): void {
        var msgBody: com.snake.socket.SC_REQUEST_SERVER_TIME = SocketDataUtil.getMsgBody(msgBase, com.snake.socket.SC_REQUEST_SERVER_TIME);
        var msgRequestTimeBody = msgBody as com.snake.socket.SC_REQUEST_SERVER_TIME;
        var serverTimestamp = msgRequestTimeBody.time;
        this.requestTime++;
        // 2. 计算时间差
        const clientRecvTime = Date.now();
        var clientTimestamp = (clientRecvTime + this.clientSendTime) / 2;
        var serverTimeOffset = clientTimestamp - serverTimestamp;
        RoomWebSocket.serverTimeOffsets.push(serverTimeOffset);

        var delaT = (clientRecvTime - this.clientSendTime) / 2;
        RoomWebSocket.delaTs.push(delaT);

        console.log(
            "TEST_TIME: " + "this.requestTime: " + this.requestTime,
            "clientRecvTime: " + clientRecvTime,
            "clientSendTime: " + this.clientSendTime,
            "clientTimestamp: " + clientTimestamp,
            "serverTimestamp: " + serverTimestamp,
            "serverTimeOffset: " + serverTimeOffset,
            "delaT: " + delaT
        );

        if (this.requestTime > 4) {
            RoomWebSocket.serverTimeOffsets.sort((a, b) => Math.abs(a) - Math.abs(b)); // 按 Time 升序排序
            RoomWebSocket.serverTimeOffsets.pop();
            var totalServerTimeOffset = 0;
            var serverTimeOffsetLen = RoomWebSocket.serverTimeOffsets.length;
            for (var i: number = 0; i < serverTimeOffsetLen; i++) {
                totalServerTimeOffset += RoomWebSocket.serverTimeOffsets[i];
            }
            serverTimeOffset = Math.round(totalServerTimeOffset / serverTimeOffsetLen);
            RoomWebSocket.serverTimeOffset = serverTimeOffset;

            RoomWebSocket.delaTs.sort((a, b) => a - b); // 按 enterTime 升序排序
            RoomWebSocket.delaTs.pop();
            var totalDelaT = 0;
            var delaTLen = RoomWebSocket.delaTs.length;
            for (var i: number = 0; i < delaTLen; i++) {
                totalDelaT += RoomWebSocket.delaTs[i];
            }
            delaT = Math.round(totalDelaT / delaTLen);

            RoomWebSocket.delaT = delaT;

            console.log("TEST_TIME: " + "serverTimeOffset: " + RoomWebSocket.serverTimeOffset + ", delaT: " + RoomWebSocket.delaT);

            this.requestTime = 0;
            RoomWebSocket.serverTimeOffsets = [];
            RoomWebSocket.delaTs = [];
            this.onGetEnterRoomData();
        } else {
            this.onRequestTime();
        }
    }

