    /** 停止发送心跳消息 */
    stopHeartbearTimer() {
        Laya.timer.clear(this, this.sendHeartBeat);
        this._heartBeatMissed = 0;
    }

    heartbeatTimer() {
        this.stopHeartbearTimer();
        this.sendHeartBeat();
        Laya.timer.loop(this._heartBeatInterval, this, this.sendHeartBeat);
    }

    lastheartBeatTime: number = 0;

    /** 大厅心跳超时次数 */
    private _heartBeatMissed: number = 0;

    /** 大厅心跳超时最大次数 5*/
    private _heartBeatMissedMax: number = 10;

    /** 心跳发送间隔 30 * 1000 */
    private _heartBeatInterval: number = 3 * 1000;
    /** 发送心跳 */
    sendHeartBeat() {
        if (!FrameSyncManager.frameNetQueue.isStart) return;
        this.lastheartBeatTime = Date.now();
        console.log('%c WSM', 'color:#2a5caa', 'sendHeartBeat 发送大厅心跳', this._heartBeatMissed);
        RoomWebSocket.sendData(com.snake.socket.MessageType.MSG_HEART_BEAT, null);
        this._heartBeatMissed += 1;
        if (this._heartBeatMissed >= this._heartBeatMissedMax) {
            console.log("发送大厅心跳超过最大次数,关闭Socket", this._heartBeatMissed);
            this.stopHeartbearTimer();
            RoomWebSocket.close();
            Quick.popMatchErrorToMain();
        }
    }

    onHeartBeat() {
        this._heartBeatMissed = -1;
        if (this.lastheartBeatTime > 0) {
            this.updateNetworkLatency(this.lastheartBeatTime);
        }
    }

