const { regClass } = Laya;
import { AniSkBase } from "./AniSk.generated";

@regClass('2rJV0EbMT9K2L6+6HOpDHw==')
export class AniSk extends AniSkBase {
    public static aniSkPrefab = "aniSkPrefab";

    public isReady: boolean = false;

    public needChangeAni: boolean = true;

    public sk: Laya.SpineSkeleton;

    private animationName: string;

    private loop: boolean = true;

    private spineTemplet: Laya.SpineTemplet;

    private templateUrl: string;

    private isInited: boolean = false;

    public constructor() {
        super();
    }

    onEnable(): void {
        this.sk = this.box_sk; //.getComponent(Laya.Spine2DRenderNode);
        this.sk.on(Laya.Event.READY, this, this.onSkReady);
        // this.sk.loop = this.loop;
        console.log("onEnable: + this.animationName： " + this.animationName);
        if (this.animationName) this.sk.animationName = this.animationName;
        if (this.spineTemplet) {
            // this.box_sk.on(Laya.Event.READY, this, this.onSkReady);
            this.sk.templet = this.spineTemplet;
            console.log("onEnable: + this.spineTemplet ");
        } else if (this.templateUrl) {
            Laya.loader.load(this.templateUrl, Laya.Loader.SPINE).then((templet: Laya.SpineTemplet) => {
                //创建spine动画
                if (this.destroyed) {
                    return;
                }
                this.sk.templet = templet;
                console.log("this.templateUrl: " + this.templateUrl);
                //按索引播放动画
                // this.spineAni.play(this.spineAniIndex, true);
            });
            // this.spineTemplet = new Laya.SpineTemplet();
        } else {
            if (!this.animationName) this.sk.animationName = "animation";
        }
        this.isInited = true;
    }

    private onSkReady() {
        this.isReady = true;
        console.log("onSkReady this.visible: " + this.visible);
    }

    public play(nameOrIndex: any, loop: boolean, force?: boolean, start?: number, end?: number, freshSkin?: boolean, playAudio?: boolean) {
        if (!this.isReady) {
            console.log("动画未准备好，不能play");
            return;
        }
        this.sk.play(nameOrIndex, loop, force, start, end, freshSkin, playAudio);
    }

    public stop() {
        if (!this.isReady) {
            console.log("动画未准备好，不能stop");
            return;
        }
        this.sk.stop();
    }

    init(spineTemplet: Laya.SpineTemplet, animationName: string = "animation", loop: boolean = true) {
        console.log("init: ", animationName, spineTemplet);
        this.animationName = animationName;
        this.spineTemplet = spineTemplet;
        this.loop = loop;
        this.visible = true;
        if (this.isInited) {
            if (this.animationName) this.sk.animationName = this.animationName;
            this.sk.templet = this.spineTemplet;
        }
    }

    initUrl(templateUrl: string, animationName: string = "animation", loop: boolean = true) {
        console.log("initUrl: ", templateUrl);
        this.animationName = animationName;
        this.templateUrl = templateUrl;
        this.loop = loop;
        this.visible = true;
        if (this.isInited) {
            Laya.loader.load(this.templateUrl, Laya.Loader.SPINE).then((templet: Laya.SpineTemplet) => {
                //创建spine动画
                if (this.destroyed) {
                    return;
                }
                if (this.animationName) this.sk.animationName = this.animationName;
                this.sk.templet = templet;
                console.log("this.templateUrl: " + this.templateUrl);
            });
        }
    }

    onDisable(): void {
        Laya.Pool.recover(AniSk.aniSkPrefab, this);
        this.box_sk.off(Laya.Event.READY, this, this.onSkReady);
        this.sk.templet = null;
    }
}
