const { regClass } = Laya;
import GameResourceManager from "../../common/GameResourceManager";
import { FoodItem } from "../../data/sheetItem/snake/FoodItem";
import { MatchSnakeBeanSprBase } from "./MatchSnakeBeanSpr.generated";

@regClass('j4yWA5APT7ipho7IOx4ryg==')
export class MatchSnakeBeanSpr extends MatchSnakeBeanSprBase {
    /**
     * 初始化豆子，加载豆子图片
     * @param x 豆子的 x 坐标
     * @param y 豆子的 y 坐标
     */
    init(foodItem: FoodItem): void {
        this.skin = GameResourceManager.getFoodIcon(foodItem.icon);
        // this.startScalingAnimation();
    }

    private minScale: number = 1; // 最小缩放比例
    private maxScale: number = 1.2; // 最大缩放比例
    private minDuration: number = 800; // 最小动画时间（毫秒）
    private maxDuration: number = 1200; // 最大动画时间（毫秒）
    private startScalingAnimation() {
        // 生成随机的缩放比例和动画时间
        let randomScale = this.minScale + Math.random() * (this.maxScale - this.minScale);
        let randomDuration = this.minDuration + Math.random() * (this.maxDuration - this.minDuration);

        // 创建放大动画
        Laya.Tween.to(
            this,
            { scaleX: randomScale, scaleY: randomScale },
            randomDuration,
            null,
            Laya.Handler.create(this, () => {
                // 动画完成后的回调，创建缩小动画
                let nextRandomScale = this.minScale + Math.random() * (1 - this.minScale); // 缩小到1以下的一个随机比例
                let nextRandomDuration = this.minDuration + Math.random() * (this.maxDuration - this.minDuration);
                Laya.Tween.to(
                    this,
                    { scaleX: nextRandomScale, scaleY: nextRandomScale },
                    nextRandomDuration,
                    null,
                    Laya.Handler.create(this, this.startScalingAnimation)
                );
            }),
            -1,
            true
        ); // -1 表示不限制次数，true 表示使用缓动效果
    }

    onDisable(): void {
        Laya.Tween.clearAll(this);
    }
}
